"""钱包审计事件存储（仅追加）。

磁盘布局（data_dir 下）::

    audit/<wallet_id>.json   该钱包的审计事件日志（seq 从 1 起单调递增）

文件形如::

    {"wallet_id": "w1",
     "next_seq": 4,
     "events": [
       {"seq": 1, "type": "policy_updated", "at": "...Z",
        "request_id": null, "actor_id": null,
        "reason": null, "details": {...}},
       ...
     ]}

关键性质：
- seq 从 1 开始，写入后立即持久化；服务重启后续写，seq 接续文件中的
  next_seq（也兼容仅依据末尾事件 seq 推断的旧文件）；
- 仅追加：只在 events 末尾追加，从不修改/删除历史事件；
- 写入采用同目录临时文件 + os.replace 原子替换；
- 调用方（service）在同一把每钱包事务锁内完成"状态变更 + 事件追加"，
  事件追加失败时回滚状态，保证状态与事件原子。
"""

from __future__ import annotations

import os
import threading
from typing import Optional

from .store import (
    CorruptDataError,
    WalletStore,
    _check_id,
    _SAFE_ID,
    parse_utc_iso,
)


def _safe_id_match(value: str) -> bool:
    return bool(_SAFE_ID.match(value))

#: 审计事件类型
TYPE_POLICY_UPDATED = "policy_updated"
TYPE_REQUEST_CREATED = "request_created"
TYPE_REQUEST_APPROVED = "request_approved"
TYPE_REQUEST_REJECTED = "request_rejected"
TYPE_REQUEST_EXPIRED = "request_expired"
TYPE_REQUEST_SIGNED = "request_signed"
TYPE_SHARE_ROTATION_PREPARED = "share_rotation_prepared"
TYPE_SHARE_ROTATION_ACTIVATED = "share_rotation_activated"
TYPE_ASSET_OPERATION_COMMITTED = "asset_operation_committed"
TYPE_TRANSACTION_POLICY_UPDATED = "transaction_policy_updated"
TYPE_SESSION_EVENT = "session_event"
TYPE_SESSION_PARTICIPANT_REPLACED = "session_participant_replaced"
TYPE_SESSION_TAKEOVER = "session_takeover"

#: 单字母缩写 -> 完整类型（P/C/A/R/E/S）
EVENT_TYPES = {
    "P": TYPE_POLICY_UPDATED,
    "C": TYPE_REQUEST_CREATED,
    "A": TYPE_REQUEST_APPROVED,
    "R": TYPE_REQUEST_REJECTED,
    "E": TYPE_REQUEST_EXPIRED,
    "S": TYPE_REQUEST_SIGNED,
}


class AuditStore:
    """审计事件日志的仅追加文件存储（一个钱包一个文件）。"""

    def __init__(self, data_dir: str) -> None:
        self._data_dir = data_dir
        self._audit_dir = os.path.join(data_dir, "audit")
        self._lock = threading.Lock()

    def _path(self, wallet_id: str) -> str:
        _check_id("wallet_id", wallet_id)
        return os.path.join(self._audit_dir, wallet_id + ".json")

    @staticmethod
    def _event_shape_ok(event: object) -> bool:
        """单条审计事件的严格形状：

        seq 为非布尔正整数；type 为非空字符串；at 为可解析的 UTC 时间；
        request_id/actor_id/reason 为 null 或字符串；details 为对象。
        details 内部各事件类型的语义由相应恢复路径（轮换链/会话动作序列/
        账本对账）负责，全局加载不重复解释。"""
        if not isinstance(event, dict):
            return False
        seq = event.get("seq")
        if not isinstance(seq, int) or isinstance(seq, bool) or seq < 1:
            return False
        if not isinstance(event.get("type"), str) or not event["type"]:
            return False
        if parse_utc_iso(event.get("at")) is None:
            return False
        for key in ("request_id", "actor_id", "reason"):
            value = event.get(key)
            if value is not None and not isinstance(value, str):
                return False
        if not isinstance(event.get("details"), dict):
            return False
        return True

    def _read_strict(self, wallet_id: str) -> Optional[dict]:
        """读取并严格校验审计文件；文件不存在返回 None。

        以下现场一律视为不可对账的数据损坏（CorruptDataError），绝不静默
        归一为空日志后覆盖历史：JSON 不可解析、顶层不是对象、events 缺失
        或不是列表、wallet_id 字段不匹配、任一事件形状非法、seq 不从 1
        起 / 不连续 / 有重号、记录的 next_seq 与实际最大 seq 矛盾。
        """
        path = self._path(wallet_id)
        data = WalletStore._read_json(path)
        if data is None:
            return None
        if not isinstance(data, dict):
            raise CorruptDataError(
                f"audit log {path!r} top-level value is not an object"
            )
        recorded_wallet = data.get("wallet_id")
        if recorded_wallet is not None and recorded_wallet != wallet_id:
            raise CorruptDataError(
                f"audit log {path!r} wallet_id {recorded_wallet!r} does not "
                f"match its file name {wallet_id!r}"
            )
        events = data.get("events")
        if "events" not in data or not isinstance(events, list):
            raise CorruptDataError(
                f"audit log {path!r} has no list-valued 'events'"
            )
        seqs: list[int] = []
        for event in events:
            if not self._event_shape_ok(event):
                raise CorruptDataError(
                    f"audit log {path!r} has a malformed event"
                )
            seqs.append(event["seq"])
        # seq 必须恰为 1..N：不重号、不缺口、单调（物理顺序允许被外部重排，
        # 查询始终按 seq 升序；但 seq 集合本身必须连续）。
        if sorted(seqs) != list(range(1, len(seqs) + 1)):
            raise CorruptDataError(
                f"audit log {path!r} has a non-contiguous or duplicated seq"
            )
        stored_next = data.get("next_seq")
        if stored_next is not None:
            if (
                not isinstance(stored_next, int)
                or isinstance(stored_next, bool)
                or stored_next != len(events) + 1
            ):
                raise CorruptDataError(
                    f"audit log {path!r} next_seq disagrees with its events"
                )
        return data

    def check_log(self, wallet_id: str) -> None:
        """只读严格校验审计文件；损坏抛 CorruptDataError/OSError。
        文件不存在（尚无事件）视为正常空状态。"""
        _check_id("wallet_id", wallet_id)
        self._read_strict(wallet_id)

    def list_audit_wallet_ids(self) -> list[str]:
        """返回存在审计文件的全部 wallet_id（启动恢复扫描用）。"""
        try:
            names = os.listdir(self._audit_dir)
        except FileNotFoundError:
            return []
        return sorted(
            name[: -len(".json")]
            for name in names
            if name.endswith(".json")
            and _safe_id_match(name[: -len(".json")])
        )

    def _read(self, wallet_id: str) -> Optional[dict]:
        return self._read_strict(wallet_id)

    def append_event(self, wallet_id: str, event: dict) -> dict:
        """原子追加一条事件，分配下一个 seq 并持久化，返回含 seq/at 的记录。

        seq 从 1 起；同一 wallet 的写入在此串行化。调用方负责在更大的
        每钱包事务锁内把状态变更与本调用绑定（失败时回滚状态）。

        既有日志损坏 / seq 矛盾时抛 CorruptDataError，绝不把历史清空后
        继续写（那会用一条新事件覆盖全部审计历史）。
        """
        path = self._path(wallet_id)
        with self._lock:
            data = self._read_strict(wallet_id)
            if data is None:
                data = {"wallet_id": wallet_id, "next_seq": 1, "events": []}
            events = data["events"]
            # 严格加载已保证 1..N 连续：下一个 seq 直接取 N+1，
            # 与 next_seq（兼容缺字段的旧文件）一致。
            next_seq = len(events) + 1
            stamped = dict(event)
            stamped["seq"] = next_seq
            events.append(stamped)
            data["next_seq"] = next_seq + 1
            WalletStore._atomic_write(path, data)
            return stamped

    def find_event_by_request(
        self,
        wallet_id: str,
        event_type: str,
        request_id: str,
    ) -> Optional[dict]:
        """按 (类型, request_id) 查找一条已持久化事件，不存在返回 None。

        启动恢复据此判定崩溃前的资产提交事务是否已把事件落盘：事件在
        则补齐账本，事件不在则回滚为 pending。纯只读，不分配 seq。
        """
        data = self._read(wallet_id)
        if not data:
            return None
        for event in data.get("events", []):
            if (
                isinstance(event, dict)
                and event.get("type") == event_type
                and event.get("request_id") == request_id
            ):
                return dict(event)
        return None

    def find_session_event(
        self, wallet_id: str, request_id: str, action: str
    ) -> Optional[dict]:
        """按 (request_id, details.action) 查找一条 session_event。

        签名会话崩溃恢复据此判定创建/签名是否已提交：事件在则状态不可
        撤回（前滚），事件不在则回滚。纯只读，不分配 seq。
        """
        for event in self.session_events(wallet_id).get(request_id, []):
            details = event.get("details")
            if isinstance(details, dict) and details.get("action") == action:
                return dict(event)
        return None

    def session_events(self, wallet_id: str) -> dict[str, list[dict]]:
        """返回该钱包全部 session_event，按 request_id（会话 id）分组。

        签名会话崩溃恢复一次性读取审计文件，据此判定每个会话哪些动作
        （created/share_received/expired/signed）已经提交。纯只读。"""
        data = self._read(wallet_id)
        result: dict[str, list[dict]] = {}
        if not data:
            return result
        for event in data.get("events", []):
            if not isinstance(event, dict):
                continue
            if event.get("type") != TYPE_SESSION_EVENT:
                continue
            request_id = event.get("request_id")
            if isinstance(request_id, str):
                result.setdefault(request_id, []).append(dict(event))
        return result

    def _events_grouped_by_request(
        self, wallet_id: str, event_type: str
    ) -> dict[str, list[dict]]:
        """返回该钱包指定类型的全部事件，按 request_id 分组，组内按 seq
        升序。纯只读，不分配 seq。"""
        data = self._read(wallet_id)
        result: dict[str, list[dict]] = {}
        if not data:
            return result
        for event in data.get("events", []):
            if not isinstance(event, dict):
                continue
            if event.get("type") != event_type:
                continue
            request_id = event.get("request_id")
            if isinstance(request_id, str):
                result.setdefault(request_id, []).append(dict(event))
        for events in result.values():
            events.sort(key=lambda e: e.get("seq", 0))
        return result

    def session_participant_replaced_events(
        self, wallet_id: str
    ) -> dict[str, list[dict]]:
        """返回该钱包全部 session_participant_replaced 事件，按 request_id
        （会话 id）分组，组内按 seq 升序。

        会话参与者替换的崩溃恢复与幂等重放据此判定哪些替换已经提交
        （事件在则替换不可撤回）。纯只读，不分配 seq。"""
        return self._events_grouped_by_request(
            wallet_id, TYPE_SESSION_PARTICIPANT_REPLACED
        )

    def session_takeover_events(
        self, wallet_id: str
    ) -> dict[str, list[dict]]:
        """返回该钱包全部 session_takeover 事件，按 request_id（会话 id）
        分组，组内按 seq 升序。

        两阶段参与者接管的崩溃恢复与幂等重放据此判定各阶段是否已提交
        （事件在则该阶段不可撤回）。纯只读，不分配 seq。"""
        return self._events_grouped_by_request(
            wallet_id, TYPE_SESSION_TAKEOVER
        )

    def activated_rotation_events(self, wallet_id: str) -> dict[str, dict]:
        """返回该钱包已落盘的 share_rotation_activated 事件映射
        ``{rotation_id: event}``。

        启动/运行时轮换恢复据此判定激活是否已提交（事件在则前滚为
        active，事件不在则回滚 prepared）。每个 rotation 至多一条激活事件；
        同一 rotation_id 出现两条激活事件属于不可对账的重复提交点，抛
        CorruptDataError（fail-closed），绝不任取一条。纯只读。
        """
        return self._rotation_events(
            wallet_id, TYPE_SHARE_ROTATION_ACTIVATED, "activated"
        )

    def prepared_rotation_events(self, wallet_id: str) -> dict[str, dict]:
        """返回该钱包已落盘的 share_rotation_prepared 事件映射
        ``{rotation_id: event}``。

        恢复据此判定轮换首次准备是否已提交（事件在则 prepared 记录合法；
        记录在但准备事件缺失说明记录是崩溃窗口残留）。准备记录在暂存
        失效被安全删除后允许以同 rotation_id 重新准备，因此同一 id 可能
        有多条准备事件，这里以最后一条为准、不报错；真正唯一的提交点是
        share_rotation_activated。纯只读。
        """
        return self._rotation_events(
            wallet_id, TYPE_SHARE_ROTATION_PREPARED, "prepared",
            strict_unique=False,
        )

    def _rotation_events(
        self,
        wallet_id: str,
        event_type: str,
        kind: str,
        strict_unique: bool = True,
    ) -> dict[str, dict]:
        data = self._read(wallet_id)
        result: dict[str, dict] = {}
        if not data:
            return result
        for event in data.get("events", []):
            if not isinstance(event, dict):
                continue
            if event.get("type") != event_type:
                continue
            details = event.get("details")
            rotation_id = (
                details.get("rotation_id")
                if isinstance(details, dict)
                else None
            )
            if not isinstance(rotation_id, str):
                raise CorruptDataError(
                    f"audit log for wallet {wallet_id!r} has a share rotation "
                    f"{kind} event without a rotation_id"
                )
            if strict_unique and rotation_id in result:
                raise CorruptDataError(
                    f"audit log for wallet {wallet_id!r} has multiple share "
                    f"rotation {kind} events for {rotation_id!r}"
                )
            # 非唯一（prepared）：保留 seq 最大的一条
            existing = result.get(rotation_id)
            if existing is None or (
                isinstance(event.get("seq"), int)
                and (
                    not isinstance(existing.get("seq"), int)
                    or event["seq"] > existing["seq"]
                )
            ):
                result[rotation_id] = dict(event)
        return result

    def list_events(
        self, wallet_id: str, from_seq: int = 1, limit: int = 1000
    ) -> list[dict]:
        """按 seq 升序返回 seq >= from_seq 的至多 limit 条事件。

        无日志文件或范围内无事件时返回 []。返回的是记录副本，
        调用方修改不会影响存储内容。日志损坏抛 CorruptDataError
        （由调用方 fail-closed），绝不静默返回残缺历史。
        """
        data = self._read(wallet_id)
        if not data:
            return []
        # 严格加载已保证 seq 集合为 1..N；仍按 seq 升序输出，避免外部改动
        # 事件物理顺序影响公开响应。
        events = [
            dict(event)
            for event in data["events"]
            if event["seq"] >= from_seq
        ]
        events.sort(key=lambda e: e["seq"])
        return events[:limit]

    def events_by_type(self, wallet_id: str, event_type: str) -> list[dict]:
        """返回某类型的全部事件（按 seq 升序，返回副本）。纯只读。

        账本语义恢复据此与已提交操作做双向对账：committed 事件必须与
        账本一一对应。日志损坏抛 CorruptDataError（fail-closed）。"""
        data = self._read(wallet_id)
        if not data:
            return []
        return [
            dict(event)
            for event in sorted(data["events"], key=lambda e: e["seq"])
            if event.get("type") == event_type
        ]

"""Ed25519 份额密钥与份额签名原语。

两方各持一把独立的 Ed25519 密钥：系统中任何位置都不存在"完整私钥"，
只有两个份额私钥。钱包公钥为两个份额公钥的有序拼接（64 字节），
门限签名为两个份额签名的有序拼接（128 字节），任何持有公钥的人
都可以把它拆成两把 Ed25519 公钥分别验证。
"""

from __future__ import annotations

from dataclasses import dataclass

from cryptography.hazmat.primitives.asymmetric.ed25519 import (
    Ed25519PrivateKey,
    Ed25519PublicKey,
)
from cryptography.hazmat.primitives.serialization import (
    Encoding,
    PrivateFormat,
    PublicFormat,
    NoEncryption,
)
from cryptography.exceptions import InvalidSignature

#: 单个份额被签名的载荷：signing_request_id 与 message 直接拼接
ENCODING = "utf-8"


@dataclass(frozen=True)
class ShareKey:
    """单个份额的 Ed25519 密钥对（仅服务端内部使用）。"""

    share_id: str
    private_bytes: bytes
    public_bytes: bytes


def generate_share_key(share_id: str) -> ShareKey:
    """为指定份额生成一把新的 Ed25519 密钥。"""
    private_key = Ed25519PrivateKey.generate()
    return ShareKey(
        share_id=share_id,
        private_bytes=private_key.private_bytes(
            Encoding.Raw, PrivateFormat.Raw, NoEncryption()
        ),
        public_bytes=private_key.public_key().public_bytes(
            Encoding.Raw, PublicFormat.Raw
        ),
    )


def sign_share(private_bytes: bytes, payload: bytes) -> bytes:
    """用一个份额的私钥对载荷做 Ed25519 签名。"""
    private_key = Ed25519PrivateKey.from_private_bytes(private_bytes)
    return private_key.sign(payload)


def public_key_from_private(private_bytes: bytes) -> bytes:
    """从 32 字节份额私钥推导对应的 Ed25519 公钥（启动恢复校验用）。"""
    return Ed25519PrivateKey.from_private_bytes(
        private_bytes
    ).public_key().public_bytes(Encoding.Raw, PublicFormat.Raw)


def verify_share(public_bytes: bytes, payload: bytes, signature: bytes) -> bool:
    """校验一个份额的 Ed25519 签名；任何异常都视为校验失败。"""
    try:
        public_key = Ed25519PublicKey.from_public_bytes(public_bytes)
        public_key.verify(signature, payload)
        return True
    except (InvalidSignature, ValueError):
        return False


def build_payload(signing_request_id: str, message: str) -> bytes:
    """构造份额签名载荷：signing_request_id 与 message 直接拼接。"""
    return signing_request_id.encode(ENCODING) + message.encode(ENCODING)


def combine_public_keys(share_public_keys: list[bytes]) -> bytes:
    """按份额顺序拼接两个份额公钥，形成钱包公钥（64 字节）。"""
    return b"".join(share_public_keys)


def split_public_key(public_key: bytes) -> list[bytes]:
    """把钱包公钥拆回两把份额公钥。"""
    return [public_key[:32], public_key[32:]]


def combine_signatures(share_signatures: list[bytes]) -> bytes:
    """按份额顺序拼接两个份额签名，形成门限签名（128 字节）。"""
    return b"".join(share_signatures)


def split_signature(signature: bytes) -> list[bytes]:
    """把门限签名拆回两个份额签名。"""
    return [signature[:64], signature[64:]]

"""钱包持久化：只保存份额，磁盘上不存在完整私钥。

磁盘布局（data_dir 下）::

    wallets/<wallet_id>.json        钱包元数据 + 份额公钥（无私钥）
    shares/<wallet_id>/<share_id>.json
                                    单个份额（份额私钥以 hex 保存），一份一个文件
    signatures/<wallet_id>.json     该钱包已完成的签名请求（幂等去重）
    policies/<wallet_id>.json       该钱包的审批策略（required_approvals 等）
    requests/<wallet_id>.json       该钱包的签名请求审批单（状态机）
    rotations/<wallet_id>.json      该钱包的份额轮换记录（prepared/activating/active）
    rotation-staging/<wallet_id>/<rotation_id>/
                                    轮换暂存目录：新份额私钥文件（<share_id>.json），
                                    激活期间的旧份额/钱包元数据备份（*.bak.json），
                                    激活成功后整目录删除
    audit/<wallet_id>.json          该钱包的审计事件日志（seq 从 1 起仅追加，
                                    由 audit.AuditStore 维护）
    assets/<wallet_id>.json         该钱包的资产账本：asset-operations（操作
                                    状态机 pending/committed）与 assets（每个
                                    资产的 balance/version），同一文件原子写入
    asset-intents/<wallet_id>/<operation_id>.json
                                    资产提交的"提交意图"（可恢复事务日志）：
                                    仅在 commit 事务窗口内存在，提交完成即删；
                                    崩溃后启动恢复据此判定提交是否已落事件，
                                    决定补齐账本或回滚为 pending
    transaction-policies/<wallet_id>.json
                                    该钱包的冷热钱包交易策略
                                    （mode/max_delta/allowed_assets），
                                    只含标识与整数，不含任何私钥材料
    sign-sessions/<wallet_id>.json  该钱包的可恢复签名会话（状态机
                                    collecting/ready/signed/expired）：
                                    原文、到期时间、已收份额签名（每份一个
                                    64 字节 Ed25519 签名，绝无私钥）与
                                    signed 时的 128 字节聚合签名

关键安全性质：
- 元数据文件不含任何私钥材料；
- 每个文件至多包含一个 32 字节份额私钥，两个份额分文件存放，
  任何位置都不保存拼接/聚合后的完整私钥；
- 写入采用同目录临时文件 + os.replace 原子替换；
- 进程内用一把锁串行化写操作（ThreadingHTTPServer 下安全）。
"""

from __future__ import annotations

import json
import os
import re
import shutil
import tempfile
import threading
from datetime import datetime, timedelta, timezone
from typing import Optional

from .crypto import ShareKey, combine_public_keys, public_key_from_private

#: wallet_id / rotation_id / signing_request_id 允许的字符（同时杜绝路径穿越）
_SAFE_ID = re.compile(r"^[A-Za-z0-9_-]{1,128}$")

#: share_id 允许的字符：轮换份额 id 为 <rotation_id>-share-N，最长 128+8
_SAFE_SHARE_ID = re.compile(r"^[A-Za-z0-9_-]{1,136}$")


def _check_id(kind: str, value: str) -> None:
    if not isinstance(value, str) or not _SAFE_ID.match(value):
        raise ValueError(f"invalid {kind}: {value!r}")


def _check_share_id(value: str) -> None:
    if not isinstance(value, str) or not _SAFE_SHARE_ID.match(value):
        raise ValueError(f"invalid share_id: {value!r}")


def _is_replacement_share_id(value: object) -> bool:
    """会话参与者替换份额的 id 形态：``<replacement_id>-share``。

    钱包/轮换份额（share-1、share-2、<rotation_id>-share-N）从不以
    ``-share`` 结尾，故 shares/<wallet_id>/ 下以 ``-share`` 结尾的正式
    份额文件只会来自会话参与者替换；轮换现场对账对它们豁免（其有无与
    自洽性由签名会话恢复按 session_participant_replaced 事件对账）。
    """
    return isinstance(value, str) and value.endswith("-share")


def _is_plain_int(value: object) -> bool:
    """真·整数：bool 是 int 子类，必须排除（余额/版本/delta 均不接受布尔）。"""
    return isinstance(value, int) and not isinstance(value, bool)


def _valid_safe_id(value: object) -> bool:
    return isinstance(value, str) and bool(_SAFE_ID.match(value))


def parse_utc_iso(value: object) -> Optional[datetime]:
    """严格解析 UTC 时间戳字符串。

    仅接受带时区信息的 ISO-8601 字符串（服务自身始终写 ``...Z``）；
    朴素时间（无 tz）、非字符串、不可解析或偏移非零固定值之外的内容
    一律返回 None。返回统一到 UTC 的 aware datetime，便于严格比较。
    """
    if not isinstance(value, str) or not value:
        return None
    text = value
    try:
        if text.endswith(("Z", "z")):
            text = text[:-1] + "+00:00"
        parsed = datetime.fromisoformat(text)
    except ValueError:
        return None
    if parsed.tzinfo is None:
        # 朴素时间无法判定时区，绝不按本地时间猜测
        return None
    if parsed.utcoffset() != timedelta(0):
        # 只接受 UTC（零偏移），其他时区不做隐式换算
        return None
    return parsed.astimezone(timezone.utc)


def approval_policy_shape_ok(policy: object) -> bool:
    """审批策略条目形状：wallet_id 为合法标识、required_approvals 为
    非布尔整数 1/2、timeout_seconds 为非布尔正整数。"""
    if not isinstance(policy, dict):
        return False
    if not _valid_safe_id(policy.get("wallet_id")):
        return False
    required = policy.get("required_approvals")
    if not _is_plain_int(required) or required not in (1, 2):
        return False
    timeout = policy.get("timeout_seconds")
    return _is_plain_int(timeout) and timeout > 0


def transaction_policy_shape_ok(policy: object) -> bool:
    """交易策略条目形状：mode 仅 hot/cold、max_delta 为非布尔正整数、
    allowed_assets 为非空数组且每项匹配安全 id。"""
    if not isinstance(policy, dict):
        return False
    if policy.get("mode") not in ("hot", "cold"):
        return False
    if not _is_plain_int(policy.get("max_delta")) or policy["max_delta"] <= 0:
        return False
    assets = policy.get("allowed_assets")
    if not isinstance(assets, list) or not assets:
        return False
    return all(_valid_safe_id(asset) for asset in assets)


def _asset_entry_shape_ok(entry: object) -> bool:
    """资产条目形状：恰需非布尔整数 balance/version。"""
    if not isinstance(entry, dict):
        return False
    return _is_plain_int(entry.get("balance")) and _is_plain_int(
        entry.get("version")
    )


def _asset_operation_shape_ok(key: str, record: object) -> bool:
    """资产操作条目形状：必须含合法 operation_id/asset_id、非布尔整数
    delta、state 只能为 pending/committed；服务正常写入还带非布尔整数
    balance/version 快照，若存在则同样必须为非布尔整数。"""
    if not isinstance(record, dict):
        return False
    operation_id = record.get("operation_id")
    asset_id = record.get("asset_id")
    if not _valid_safe_id(operation_id) or operation_id != key:
        return False
    if not _valid_safe_id(asset_id):
        return False
    if not _is_plain_int(record.get("delta")) or record.get("delta") == 0:
        return False
    if record.get("state") not in ("pending", "committed"):
        return False
    for optional_int in ("balance", "version"):
        if optional_int in record and not _is_plain_int(
            record[optional_int]
        ):
            return False
    return True


class DuplicateWalletError(Exception):
    """wallet_id 已存在。"""


class RecoveryError(Exception):
    """启动/运行时恢复无法把磁盘现场对账到一致状态。

    触发即说明数据目录损坏或被外部篡改，继续服务可能暴露半完成状态或
    写错密钥，因此调用方必须阻止服务就绪（fail-closed），不得静默跳过。
    """


class CorruptDataError(ValueError):
    """本应是 JSON 对象的持久化文件无法解析（损坏或被外部篡改）。

    是 ValueError 的子类：既有的宽松 ``except ValueError``（如把不可解析
    意图纳入对账、把损坏暂存判为无效）行为不变；业务/HTTP 边界则可据此
    把"解析异常"与"非法 id"区分开——前者 fail-closed（503/阻止就绪），
    后者才是 400。
    """


class WalletStore:
    """钱包、份额与已完成签名请求的文件存储。"""

    def __init__(self, data_dir: str) -> None:
        self._data_dir = data_dir
        self._wallets_dir = os.path.join(data_dir, "wallets")
        self._shares_dir = os.path.join(data_dir, "shares")
        self._signatures_dir = os.path.join(data_dir, "signatures")
        self._policies_dir = os.path.join(data_dir, "policies")
        self._requests_dir = os.path.join(data_dir, "requests")
        self._rotations_dir = os.path.join(data_dir, "rotations")
        self._rotation_staging_dir = os.path.join(data_dir, "rotation-staging")
        self._assets_dir = os.path.join(data_dir, "assets")
        self._asset_intents_dir = os.path.join(data_dir, "asset-intents")
        self._transaction_policies_dir = os.path.join(
            data_dir, "transaction-policies"
        )
        self._sign_sessions_dir = os.path.join(data_dir, "sign-sessions")
        os.makedirs(self._wallets_dir, exist_ok=True)
        os.makedirs(self._shares_dir, exist_ok=True)
        os.makedirs(self._signatures_dir, exist_ok=True)
        os.makedirs(self._policies_dir, exist_ok=True)
        os.makedirs(self._requests_dir, exist_ok=True)
        os.makedirs(self._rotations_dir, exist_ok=True)
        os.makedirs(self._rotation_staging_dir, exist_ok=True)
        os.makedirs(self._assets_dir, exist_ok=True)
        os.makedirs(self._asset_intents_dir, exist_ok=True)
        os.makedirs(self._transaction_policies_dir, exist_ok=True)
        os.makedirs(self._sign_sessions_dir, exist_ok=True)
        self._lock = threading.Lock()

    @property
    def data_dir(self) -> str:
        return self._data_dir

    # ---- 内部工具 -------------------------------------------------------

    def _wallet_path(self, wallet_id: str) -> str:
        _check_id("wallet_id", wallet_id)
        return os.path.join(self._wallets_dir, wallet_id + ".json")

    def _share_path(self, wallet_id: str, share_id: str) -> str:
        _check_id("wallet_id", wallet_id)
        _check_share_id(share_id)
        return os.path.join(
            self._shares_dir, wallet_id, share_id + ".json"
        )

    def _signatures_path(self, wallet_id: str) -> str:
        _check_id("wallet_id", wallet_id)
        return os.path.join(self._signatures_dir, wallet_id + ".json")

    def _policy_path(self, wallet_id: str) -> str:
        _check_id("wallet_id", wallet_id)
        return os.path.join(self._policies_dir, wallet_id + ".json")

    def _requests_path(self, wallet_id: str) -> str:
        _check_id("wallet_id", wallet_id)
        return os.path.join(self._requests_dir, wallet_id + ".json")

    @staticmethod
    def _atomic_write(path: str, data: dict) -> None:
        directory = os.path.dirname(path)
        os.makedirs(directory, exist_ok=True)
        fd, tmp_path = tempfile.mkstemp(dir=directory, prefix=".tmp-", suffix=".json")
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as f:
                json.dump(data, f, ensure_ascii=False, indent=2, sort_keys=True)
                f.write("\n")
            os.replace(tmp_path, path)
        except BaseException:
            try:
                os.unlink(tmp_path)
            except FileNotFoundError:
                pass
            raise

    @staticmethod
    def _read_json(path: str) -> Optional[dict]:
        try:
            with open(path, "r", encoding="utf-8") as f:
                return json.load(f)
        except FileNotFoundError:
            return None
        except json.JSONDecodeError as exc:
            # 文件存在但损坏/被外部篡改：区别于"文件不存在"，按不可对账
            # 的数据损坏处理（CorruptDataError 是 ValueError 子类）。
            raise CorruptDataError(
                f"cannot parse JSON file {path!r}: {exc.msg}"
            ) from exc

    # ---- 钱包与份额 -----------------------------------------------------

    def create_wallet(
        self, wallet_id: str, shares: list[ShareKey], created_at: str
    ) -> None:
        """原子创建钱包元数据与各份额文件；重复时抛 DuplicateWalletError。"""
        meta_path = self._wallet_path(wallet_id)
        meta = {
            "wallet_id": wallet_id,
            "created_at": created_at,
            "public_key": b"".join(s.public_bytes for s in shares).hex(),
            "shares": [
                {"share_id": s.share_id, "public_key": s.public_bytes.hex()}
                for s in shares
            ],
        }
        share_records = [
            (
                self._share_path(wallet_id, s.share_id),
                {
                    "share_id": s.share_id,
                    "public_key": s.public_bytes.hex(),
                    # 仅该份额自己的私钥；系统中不存在完整私钥
                    "private_key": s.private_bytes.hex(),
                },
            )
            for s in shares
        ]
        with self._lock:
            if os.path.exists(meta_path):
                raise DuplicateWalletError(wallet_id)
            for path, record in share_records:
                self._atomic_write(path, record)
            self._atomic_write(meta_path, meta)

    def get_wallet(self, wallet_id: str) -> Optional[dict]:
        """返回钱包元数据（不含私钥），不存在返回 None。"""
        return self._read_json(self._wallet_path(wallet_id))

    def has_wallet(self, wallet_id: str) -> bool:
        return os.path.exists(self._wallet_path(wallet_id))

    def get_share(self, wallet_id: str, share_id: str) -> Optional[dict]:
        """返回单个份额记录（含该份额私钥 hex），不存在返回 None。"""
        return self._read_json(self._share_path(wallet_id, share_id))

    # ---- 签名请求 -------------------------------------------------------

    def save_signature(
        self, wallet_id: str, signing_request_id: str, record: dict
    ) -> Optional[dict]:
        """原子地保存一条已完成签名。

        在同一把锁内先查重：若该 signing_request_id 已有结果，则不覆盖、
        直接返回已有记录；否则写入并返回 None。
        """
        _check_id("signing_request_id", signing_request_id)
        path = self._signatures_path(wallet_id)
        with self._lock:
            all_records = self._read_json(path) or {}
            existing = all_records.get(signing_request_id)
            if existing is not None:
                return existing
            all_records[signing_request_id] = record
            self._atomic_write(path, all_records)
            return None

    def get_signature(
        self, wallet_id: str, signing_request_id: str
    ) -> Optional[dict]:
        """返回某签名请求的已有结果，不存在返回 None。"""
        _check_id("signing_request_id", signing_request_id)
        all_records = self._read_json(self._signatures_path(wallet_id))
        if not all_records:
            return None
        return all_records.get(signing_request_id)

    # ---- 审批策略 -------------------------------------------------------

    def save_policy(self, wallet_id: str, policy: dict) -> None:
        """原子地写入（或覆盖）钱包的审批策略。"""
        path = self._policy_path(wallet_id)
        with self._lock:
            self._atomic_write(path, policy)

    def get_policy(self, wallet_id: str) -> Optional[dict]:
        """返回钱包的审批策略，未设置返回 None。

        文件存在但形状损坏（标识/整数字段缺失或类型非法）时抛
        CorruptDataError（ValueError 子类），绝不返回残缺策略让下游
        读到“旧/坏策略”后按 KeyError/TypeError 继续判定。"""
        policy = self._read_json(self._policy_path(wallet_id))
        if policy is not None and not approval_policy_shape_ok(policy):
            raise CorruptDataError(
                f"approval policy for wallet {wallet_id!r} is malformed"
            )
        return policy

    # ---- 签名请求审批单 ---------------------------------------------------

    def create_request(
        self, wallet_id: str, signing_request_id: str, record: dict
    ) -> Optional[dict]:
        """原子地创建一条签名请求审批单。

        在同一把锁内先查重：若该 signing_request_id 已存在，则不覆盖、
        直接返回已有记录；否则写入并返回 None。
        """
        _check_id("signing_request_id", signing_request_id)
        path = self._requests_path(wallet_id)
        with self._lock:
            all_records = self._read_json(path) or {}
            existing = all_records.get(signing_request_id)
            if existing is not None:
                return existing
            all_records[signing_request_id] = record
            self._atomic_write(path, all_records)
            return None

    def get_request(
        self, wallet_id: str, signing_request_id: str
    ) -> Optional[dict]:
        """返回某条签名请求审批单，不存在返回 None。"""
        _check_id("signing_request_id", signing_request_id)
        all_records = self._read_json(self._requests_path(wallet_id))
        if not all_records:
            return None
        return all_records.get(signing_request_id)

    def update_request(
        self, wallet_id: str, signing_request_id: str, record: dict
    ) -> None:
        """原子地覆盖一条已存在的签名请求审批单（状态机推进用）。"""
        _check_id("signing_request_id", signing_request_id)
        path = self._requests_path(wallet_id)
        with self._lock:
            all_records = self._read_json(path) or {}
            all_records[signing_request_id] = record
            self._atomic_write(path, all_records)

    # ---- 回滚（状态/事件原子性用）----------------------------------------

    def delete_policy(self, wallet_id: str) -> None:
        """删除钱包的审批策略文件（策略事件追加失败时回滚用）。"""
        path = self._policy_path(wallet_id)
        with self._lock:
            try:
                os.unlink(path)
            except FileNotFoundError:
                pass

    # ---- 冷热钱包交易策略 -----------------------------------------------

    def _transaction_policy_path(self, wallet_id: str) -> str:
        _check_id("wallet_id", wallet_id)
        return os.path.join(
            self._transaction_policies_dir, wallet_id + ".json"
        )

    def save_transaction_policy(self, wallet_id: str, policy: dict) -> None:
        """原子地写入（或覆盖）钱包的冷热钱包交易策略。

        文件只含 mode/max_delta/allowed_assets（标识与整数/字符串），
        不含任何私钥材料。
        """
        path = self._transaction_policy_path(wallet_id)
        with self._lock:
            self._atomic_write(path, policy)

    def get_transaction_policy(self, wallet_id: str) -> Optional[dict]:
        """返回钱包的冷热钱包交易策略，未设置返回 None。

        文件存在但形状损坏时抛 CorruptDataError：绝不把残缺策略交给
        上层用于白名单/冷热判定或直接回显，统一 fail-closed（503）。"""
        policy = self._read_json(self._transaction_policy_path(wallet_id))
        if policy is not None and not transaction_policy_shape_ok(policy):
            raise CorruptDataError(
                f"transaction policy for wallet {wallet_id!r} is malformed"
            )
        return policy

    def delete_transaction_policy(self, wallet_id: str) -> None:
        """删除钱包的交易策略文件（首设时事件追加失败回滚用）。"""
        path = self._transaction_policy_path(wallet_id)
        with self._lock:
            try:
                os.unlink(path)
            except FileNotFoundError:
                pass

    def delete_request(self, wallet_id: str, signing_request_id: str) -> None:
        """删除一条签名请求审批单（创建事件追加失败时回滚用）。"""
        _check_id("signing_request_id", signing_request_id)
        path = self._requests_path(wallet_id)
        with self._lock:
            all_records = self._read_json(path)
            if not all_records or signing_request_id not in all_records:
                return
            del all_records[signing_request_id]
            if all_records:
                self._atomic_write(path, all_records)
            else:
                try:
                    os.unlink(path)
                except FileNotFoundError:
                    pass

    def delete_signature(self, wallet_id: str, signing_request_id: str) -> None:
        """删除一条已完成签名记录（签名事件追加失败时回滚用）。"""
        _check_id("signing_request_id", signing_request_id)
        path = self._signatures_path(wallet_id)
        with self._lock:
            all_records = self._read_json(path)
            if not all_records or signing_request_id not in all_records:
                return
            del all_records[signing_request_id]
            if all_records:
                self._atomic_write(path, all_records)
            else:
                try:
                    os.unlink(path)
                except FileNotFoundError:
                    pass

    # ---- 可恢复签名会话 ---------------------------------------------------

    def _sign_sessions_path(self, wallet_id: str) -> str:
        _check_id("wallet_id", wallet_id)
        return os.path.join(self._sign_sessions_dir, wallet_id + ".json")

    @staticmethod
    def _session_share_shape_ok(entry: object) -> bool:
        """已收份额条目形状：share_id 为合法标识、signature 为 hex 字符串
        且解码恰为 64 字节 Ed25519 份额签名。"""
        if not isinstance(entry, dict):
            return False
        share_id = entry.get("share_id")
        signature_hex = entry.get("signature")
        if not isinstance(share_id, str) or not _SAFE_SHARE_ID.match(share_id):
            return False
        if not isinstance(signature_hex, str):
            return False
        try:
            signature = bytes.fromhex(signature_hex)
        except ValueError:
            return False
        return len(signature) == 64

    def _session_record_shape_ok(self, key: str, record: object) -> bool:
        """签名会话记录形状的严格校验（损坏文件 fail-closed 用）。

        要求：id 为安全标识且与键一致；message 为非空字符串；
        timeout_seconds 为非布尔正整数；expires_at/created_at 为可解析的
        UTC 时间字符串；state 仅 collecting/ready/signed/expired；
        share_ids 恰为两个不重复的合法份额标识；shares 为条目数组，
        share_id 不重复且属于 share_ids 快照，每份签名恰为 64 字节；
        signed 必须带恰两份份额与 128 字节聚合签名；ready 必须恰两份；
        collecting/expired 可有 0~2 份——ready 到点同样会原子转 expired，
        故 expired 允许保留齐备份额；这两个非终态/终态不得携带聚合签名。

        状态、事件序列与份额集合的语义一致性（含逐份公钥重验与 signed
        聚合重算）由 service 层恢复对账完成：崩溃窗口内磁盘可能短暂出现
        “事件未落盘的终态”，形状合法即可加载，由恢复按提交点前滚/回滚。
        """
        if not isinstance(record, dict):
            return False
        if record.get("id") != key or not _valid_safe_id(key):
            return False
        message = record.get("message")
        if not isinstance(message, str) or not message:
            return False
        timeout = record.get("timeout_seconds")
        if not _is_plain_int(timeout) or timeout <= 0:
            return False
        if parse_utc_iso(record.get("expires_at")) is None:
            return False
        if not isinstance(record.get("created_at"), str):
            return False
        state = record.get("state")
        if state not in ("collecting", "ready", "signed", "expired"):
            return False
        expected = record.get("share_ids")
        if not isinstance(expected, list) or len(expected) != 2:
            return False
        if any(
            not isinstance(sid, str) or not _SAFE_SHARE_ID.match(sid)
            for sid in expected
        ):
            return False
        if len(set(expected)) != 2:
            return False
        shares = record.get("shares")
        if not isinstance(shares, list) or len(shares) > 2:
            return False
        seen: set[str] = set()
        for entry in shares:
            if not self._session_share_shape_ok(entry):
                return False
            sid = entry["share_id"]
            if sid in seen or sid not in expected:
                return False
            seen.add(sid)
        aggregate_hex = record.get("aggregate_signature")
        if state == "signed":
            if len(seen) != 2:
                return False
            if not isinstance(aggregate_hex, str):
                return False
            try:
                aggregate = bytes.fromhex(aggregate_hex)
            except ValueError:
                return False
            if len(aggregate) != 128:
                return False
        elif state == "ready":
            # ready 必须两份齐备；不到两份的 ready 是矛盾状态
            if len(seen) != 2:
                return False
            if aggregate_hex is not None:
                return False
        else:
            # collecting / expired：0~2 份（ready 到点同样转 expired），
            # 但不得携带聚合签名
            if aggregate_hex is not None:
                return False
        return True

    def _read_sign_sessions(self, wallet_id: str) -> dict:
        """读取并严格校验全部签名会话；文件不存在为空映射。

        文件存在但 JSON 损坏、顶层不是对象、键非安全标识或任一会话记录
        形状非法时抛 CorruptDataError：绝不静默归一为空会话，保留现场由
        上层 fail-closed（503/阻止就绪）。"""
        path = self._sign_sessions_path(wallet_id)
        data = self._read_json(path)
        if data is None:
            return {}
        if not isinstance(data, dict):
            raise CorruptDataError(
                f"sign sessions file {path!r} top-level value is not an object"
            )
        for session_id, record in data.items():
            if not _valid_safe_id(session_id) or not self._session_record_shape_ok(
                session_id, record
            ):
                raise CorruptDataError(
                    f"sign sessions file {path!r} has malformed session "
                    f"{session_id!r}"
                )
        return data

    def check_sign_sessions(self, wallet_id: str) -> None:
        """只读校验签名会话文件形状；损坏时抛 CorruptDataError/OSError。
        文件不存在（尚无会话）视为正常空状态。"""
        _check_id("wallet_id", wallet_id)
        self._read_sign_sessions(wallet_id)

    def sign_session_file_exists(self, wallet_id: str) -> bool:
        """该钱包的签名会话文件是否存在（存在即需与审计对账，哪怕为空）。"""
        return os.path.exists(self._sign_sessions_path(wallet_id))

    def list_sign_session_wallet_ids(self) -> list[str]:
        """返回存在签名会话文件的全部 wallet_id（启动恢复扫描用）。"""
        try:
            names = os.listdir(self._sign_sessions_dir)
        except FileNotFoundError:
            return []
        return sorted(
            name[: -len(".json")]
            for name in names
            if name.endswith(".json")
            and _SAFE_ID.match(name[: -len(".json")])
        )

    def create_sign_session(
        self, wallet_id: str, session_id: str, record: dict
    ) -> Optional[dict]:
        """原子地创建一条签名会话（调用方须持钱包事务锁并已查重）。

        同 id 已存在则不覆盖、直接返回已有记录；否则写入并返回 None。
        """
        _check_id("session_id", session_id)
        path = self._sign_sessions_path(wallet_id)
        with self._lock:
            all_records = self._read_sign_sessions(wallet_id)
            existing = all_records.get(session_id)
            if existing is not None:
                return existing
            all_records[session_id] = record
            self._atomic_write(path, all_records)
            return None

    def get_sign_session(
        self, wallet_id: str, session_id: str
    ) -> Optional[dict]:
        """返回某条签名会话记录（严格校验），不存在返回 None。"""
        _check_id("session_id", session_id)
        return self._read_sign_sessions(wallet_id).get(session_id)

    def list_sign_sessions(self, wallet_id: str) -> list[dict]:
        """返回某钱包全部签名会话记录（严格校验，按 id 排序）。"""
        records = self._read_sign_sessions(wallet_id)
        return [dict(records[key]) for key in sorted(records)]

    def update_sign_session(
        self, wallet_id: str, session_id: str, record: dict
    ) -> None:
        """原子覆盖一条已存在的签名会话（收份额/懒过期/聚合提交用）。"""
        _check_id("session_id", session_id)
        path = self._sign_sessions_path(wallet_id)
        with self._lock:
            all_records = self._read_sign_sessions(wallet_id)
            all_records[session_id] = record
            self._atomic_write(path, all_records)

    def delete_sign_session(self, wallet_id: str, session_id: str) -> None:
        """删除一条签名会话（创建事件追加失败回滚用）。"""
        _check_id("session_id", session_id)
        path = self._sign_sessions_path(wallet_id)
        with self._lock:
            all_records = self._read_sign_sessions(wallet_id)
            if session_id not in all_records:
                return
            del all_records[session_id]
            if all_records:
                self._atomic_write(path, all_records)
            else:
                try:
                    os.unlink(path)
                except FileNotFoundError:
                    pass

    # ---- 资产账本（asset-operations 与 assets）-----------------------------
    def _assets_path(self, wallet_id: str) -> str:
        _check_id("wallet_id", wallet_id)
        return os.path.join(self._assets_dir, wallet_id + ".json")

    def _read_asset_ledger(self, wallet_id: str) -> dict:
        """读取并**严格校验**资产账本（无文件时返回空结构）。

        文件存在但出现以下任一情况都视为数据损坏，抛 CorruptDataError
        （ValueError 子类），绝不把文件静默归一为空账本：
        JSON 不可解析、顶层不是对象、缺少 operations/assets、二者类型
        不是对象、操作条目字段形状非法（operation_id/asset_id 合法、
        delta/balance/version 为非布尔整数、state 仅 pending/committed）、
        资产条目 balance/version 不是非布尔整数。
        """
        path = self._assets_path(wallet_id)
        ledger = self._read_json(path)
        if ledger is None:
            # 文件尚不存在：正常的空状态（与"存在但损坏"严格区分）
            return {"operations": {}, "assets": {}}
        if not isinstance(ledger, dict):
            raise CorruptDataError(
                f"asset ledger {path!r} top-level value is not an object"
            )
        operations = ledger.get("operations")
        assets = ledger.get("assets")
        if "operations" not in ledger or not isinstance(operations, dict):
            raise CorruptDataError(
                f"asset ledger {path!r} has no object-valued 'operations'"
            )
        if "assets" not in ledger or not isinstance(assets, dict):
            raise CorruptDataError(
                f"asset ledger {path!r} has no object-valued 'assets'"
            )
        for operation_id, record in operations.items():
            if not _valid_safe_id(operation_id) or not (
                _asset_operation_shape_ok(operation_id, record)
            ):
                raise CorruptDataError(
                    f"asset ledger {path!r} has malformed operation "
                    f"{operation_id!r}"
                )
        for asset_id, entry in assets.items():
            if not _valid_safe_id(asset_id) or not _asset_entry_shape_ok(entry):
                raise CorruptDataError(
                    f"asset ledger {path!r} has malformed asset {asset_id!r}"
                )
        return {"operations": operations, "assets": assets}

    def check_asset_ledger(self, wallet_id: str) -> None:
        """只读校验资产账本形状；损坏时抛 CorruptDataError/OSError。
        文件不存在（尚无账本）视为正常空状态，不报错。"""
        _check_id("wallet_id", wallet_id)
        self._read_asset_ledger(wallet_id)

    def asset_ledger_file_exists(self, wallet_id: str) -> bool:
        """该钱包的账本文件是否存在（存在即需语义/事件对账，哪怕为空）。"""
        return os.path.exists(self._assets_path(wallet_id))

    def check_asset_ledger_semantics(self, wallet_id: str) -> dict:
        """在形状合法的前提下，对账本做**语义**对账（纯账本，不读审计）。

        形状合法只能保证字段类型正确，无法发现 JSON 可解析但自相矛盾的
        现场；本方法按正常服务只会写出的不变量重算：

        - 每条操作（pending/committed）都必须携带非布尔整数
          balance/version 快照（服务落盘的 R 恒含这两项）；
        - 对每个资产，按 version 升序的 committed 操作必须恰为
          version 1..K（不缺号、不重号、起点为 1），且余额从 0 起按
          delta 逐条累加，每个前缀余额都必须非负、与记录快照一致；
        - K>=1 时资产条目必须恰为 {balance: 末态, version: K}；
          K=0（只有/没有 pending）时不得存在资产条目；
        - pending 操作的 (balance, version) 快照必须等于该资产某条已提交
          前缀（version 在 0..K 内且余额与重算前缀一致）——快照是创建
          时刻的账本状态，提交交错时它可能落后于当前末态。

        任一矛盾抛 CorruptDataError（fail-closed，保留现场），绝不带
        矛盾账本继续创建/提交/查询。返回校验后的账本供上层与审计对账。
        """
        _check_id("wallet_id", wallet_id)
        ledger = self._read_asset_ledger(wallet_id)
        operations = ledger["operations"]
        assets = ledger["assets"]

        asset_ids: set[str] = set()
        pending_by_asset: dict[str, list[dict]] = {}
        committed_by_asset: dict[str, list[dict]] = {}
        for record in operations.values():
            asset_id = record["asset_id"]
            asset_ids.add(asset_id)
            if (
                not _is_plain_int(record.get("balance"))
                or not _is_plain_int(record.get("version"))
            ):
                raise CorruptDataError(
                    f"asset ledger for wallet {wallet_id!r} operation "
                    f"{record.get('operation_id')!r} lacks a snapshot"
                )
            if record["state"] == "committed":
                committed_by_asset.setdefault(asset_id, []).append(record)
            else:
                pending_by_asset.setdefault(asset_id, []).append(record)

        for asset_id, entry in assets.items():
            asset_ids.add(asset_id)

        prefix_balances: dict[str, list[int]] = {}
        for asset_id in asset_ids:
            commits = committed_by_asset.get(asset_id, [])
            ordered = sorted(commits, key=lambda r: r["version"])
            versions = [r["version"] for r in ordered]
            k_total = len(ordered)
            if versions != list(range(1, k_total + 1)):
                raise CorruptDataError(
                    f"asset ledger for wallet {wallet_id!r} asset "
                    f"{asset_id!r} has non-contiguous committed versions"
                )
            balances = [0]
            balance = 0
            for ordinal, record in enumerate(ordered, start=1):
                if record["version"] != ordinal:
                    raise CorruptDataError(
                        f"asset ledger for wallet {wallet_id!r} asset "
                        f"{asset_id!r} version ordering is inconsistent"
                    )
                balance += record["delta"]
                if balance < 0:
                    # 余额不足的提交在正常流程会被 409 拒绝：负余额前缀
                    # 只可能是外部篡改/丢失操作
                    raise CorruptDataError(
                        f"asset ledger for wallet {wallet_id!r} asset "
                        f"{asset_id!r} goes negative"
                    )
                if record["balance"] != balance:
                    raise CorruptDataError(
                        f"asset ledger for wallet {wallet_id!r} asset "
                        f"{asset_id!r} balance does not recompute"
                    )
                balances.append(balance)
            prefix_balances[asset_id] = balances

            entry = assets.get(asset_id)
            if k_total == 0:
                if entry is not None:
                    # 无任何已提交操作却存在资产条目：半完成/矛盾现场
                    raise CorruptDataError(
                        f"asset ledger for wallet {wallet_id!r} asset "
                        f"{asset_id!r} exists without committed operations"
                    )
            elif entry != {"balance": balance, "version": k_total}:
                raise CorruptDataError(
                    f"asset ledger for wallet {wallet_id!r} asset "
                    f"{asset_id!r} entry does not match its committed tail"
                )

        for asset_id, pendings in pending_by_asset.items():
            balances = prefix_balances[asset_id]
            k_total = len(balances) - 1
            for record in pendings:
                version = record["version"]
                if not 0 <= version <= k_total:
                    raise CorruptDataError(
                        f"asset ledger for wallet {wallet_id!r} operation "
                        f"{record['operation_id']!r} snapshot version is out "
                        "of the committed prefix range"
                    )
                if record["balance"] != balances[version]:
                    # pending 快照必须等于创建时刻（某条已提交前缀）的余额
                    raise CorruptDataError(
                        f"asset ledger for wallet {wallet_id!r} operation "
                        f"{record['operation_id']!r} snapshot balance does not "
                        "match the committed prefix"
                    )
        return ledger

    def list_asset_ledger_wallet_ids(self) -> list[str]:
        """返回存在资产账本文件的全部 wallet_id（启动恢复扫描用）。

        只纳入匹配安全 id 的正式账本文件，忽略原子写残留的临时文件，
        避免把临时文件名当成 wallet_id。
        """
        try:
            names = os.listdir(self._assets_dir)
        except FileNotFoundError:
            return []
        return sorted(
            name[: -len(".json")]
            for name in names
            if name.endswith(".json")
            and _SAFE_ID.match(name[: -len(".json")])
        )

    def create_asset_operation(
        self, wallet_id: str, operation_id: str, record: dict
    ) -> Optional[dict]:
        """原子地创建一条资产操作记录。

        在同一把锁内先查重：若该 operation_id 已存在，则不覆盖、
        直接返回已有记录；否则写入并返回 None。
        """
        _check_id("operation_id", operation_id)
        path = self._assets_path(wallet_id)
        with self._lock:
            ledger = self._read_asset_ledger(wallet_id)
            existing = ledger["operations"].get(operation_id)
            if isinstance(existing, dict):
                return existing
            ledger["operations"][operation_id] = record
            self._atomic_write(path, ledger)
            return None

    def get_asset_operation(
        self, wallet_id: str, operation_id: str
    ) -> Optional[dict]:
        """返回某条资产操作记录，不存在返回 None。"""
        _check_id("operation_id", operation_id)
        record = self._read_asset_ledger(wallet_id)["operations"].get(
            operation_id
        )
        return dict(record) if isinstance(record, dict) else None

    def get_asset(self, wallet_id: str, asset_id: str) -> Optional[dict]:
        """返回某资产的账本记录（balance/version），不存在返回 None。"""
        _check_id("asset_id", asset_id)
        record = self._read_asset_ledger(wallet_id)["assets"].get(asset_id)
        return dict(record) if isinstance(record, dict) else None

    def commit_asset_operation(
        self,
        wallet_id: str,
        operation_id: str,
        operation_record: dict,
        asset_id: str,
        asset_record: dict,
    ) -> None:
        """原子地提交一条资产操作：操作记录与资产 balance/version 同文件
        一次写入（调用方须持有该钱包事务锁）。"""
        _check_id("operation_id", operation_id)
        _check_id("asset_id", asset_id)
        path = self._assets_path(wallet_id)
        with self._lock:
            ledger = self._read_asset_ledger(wallet_id)
            ledger["operations"][operation_id] = operation_record
            ledger["assets"][asset_id] = asset_record
            self._atomic_write(path, ledger)

    def restore_asset_operation(
        self,
        wallet_id: str,
        operation_id: str,
        operation_record: dict,
        asset_id: str,
        asset_record: Optional[dict],
    ) -> None:
        """提交事件追加失败时回滚：恢复操作记录与资产记录
        （asset_record 为 None 表示提交前该资产无账本记录，直接删除）。"""
        _check_id("operation_id", operation_id)
        _check_id("asset_id", asset_id)
        path = self._assets_path(wallet_id)
        with self._lock:
            ledger = self._read_asset_ledger(wallet_id)
            ledger["operations"][operation_id] = operation_record
            if asset_record is None:
                ledger["assets"].pop(asset_id, None)
            else:
                ledger["assets"][asset_id] = asset_record
            self._atomic_write(path, ledger)

    # ---- 资产提交意图（可恢复事务日志）-----------------------------------

    def _asset_intent_path(self, wallet_id: str, operation_id: str) -> str:
        _check_id("wallet_id", wallet_id)
        _check_id("operation_id", operation_id)
        return os.path.join(
            self._asset_intents_dir, wallet_id, operation_id + ".json"
        )

    def write_asset_commit_intent(
        self, wallet_id: str, operation_id: str, intent: dict
    ) -> None:
        """原子写入一条资产提交意图（commit 事务第一步）。

        意图记录只含标识与整数（operation_id/asset_id/delta、提交前后
        balance/version、事件 seq），不含任何私钥材料。
        """
        path = self._asset_intent_path(wallet_id, operation_id)
        with self._lock:
            self._atomic_write(path, intent)

    def get_asset_commit_intent(
        self, wallet_id: str, operation_id: str
    ) -> Optional[dict]:
        """返回某操作的提交意图，不存在返回 None。"""
        return self._read_json(self._asset_intent_path(wallet_id, operation_id))

    def delete_asset_commit_intent(
        self, wallet_id: str, operation_id: str
    ) -> None:
        """删除提交意图（commit 事务完成/中止的最后一步）。"""
        path = self._asset_intent_path(wallet_id, operation_id)
        with self._lock:
            try:
                os.unlink(path)
            except FileNotFoundError:
                pass

    def list_asset_intent_wallet_ids(self) -> list[str]:
        """返回存在提交意图目录的全部 wallet_id。"""
        try:
            names = os.listdir(self._asset_intents_dir)
        except FileNotFoundError:
            return []
        return sorted(
            name
            for name in names
            if _SAFE_ID.match(name)
            and os.path.isdir(os.path.join(self._asset_intents_dir, name))
        )

    @staticmethod
    def valid_asset_commit_intent(operation_id: str, intent: object) -> bool:
        """校验提交意图是否具备安全回滚/前滚所需的全部标识与整数。

        正常提交写入的意图含 operation_id/asset_id/delta、提交前资产
        快照 old_asset（None 或 {balance,version}）、pending 操作记录、
        提交结果 new_balance/new_version。任一字段缺失、类型错误、布尔
        冒整、标识不匹配或前后账目不守恒都判定为无效：调用方必须
        fail-closed（保留意图现场，不回滚/前滚/清理），绝不把损坏意图
        当成空意图继续。
        """
        if not isinstance(intent, dict):
            return False
        if intent.get("operation_id") != operation_id:
            return False
        asset_id = intent.get("asset_id")
        if not _valid_safe_id(asset_id):
            return False
        delta = intent.get("delta")
        if not _is_plain_int(delta) or delta == 0:
            return False
        new_balance = intent.get("new_balance")
        new_version = intent.get("new_version")
        if not _is_plain_int(new_balance) or not _is_plain_int(new_version):
            return False
        old_asset = intent.get("old_asset")
        if old_asset is not None and not _asset_entry_shape_ok(old_asset):
            return False
        pending = intent.get("pending")
        if not _asset_operation_shape_ok(operation_id, pending):
            return False
        # pending 是创建时刻的操作快照 R，服务正常写入必带非布尔整数
        # balance/version；恢复据此还原操作，缺失即不可安全对账。
        if not _is_plain_int(pending.get("balance")) or not (
            _is_plain_int(pending.get("version"))
        ):
            return False
        if pending["state"] != "pending" or pending["asset_id"] != asset_id:
            return False
        if pending["delta"] != delta:
            return False
        old_balance = old_asset["balance"] if old_asset is not None else 0
        old_version = old_asset["version"] if old_asset is not None else 0
        return (
            new_balance == old_balance + delta
            and new_version == old_version + 1
        )

    def list_asset_intents(self, wallet_id: str) -> list[tuple[str, Optional[dict]]]:
        """返回某钱包全部提交意图 (operation_id, intent|None)。

        intent 为 None 表示文件存在但 JSON 不可解析或不是对象（原子写使
        正常流程不会出现，仅外部损坏时）：调用方必须按不可对账处理
        （fail-closed、保留现场），不得把它当成空意图清理。
        """
        _check_id("wallet_id", wallet_id)
        base = os.path.join(self._asset_intents_dir, wallet_id)
        try:
            names = os.listdir(base)
        except (FileNotFoundError, NotADirectoryError):
            return []
        result: list[tuple[str, Optional[dict]]] = []
        for name in names:
            if not name.endswith(".json"):
                continue
            operation_id = name[: -len(".json")]
            if not _SAFE_ID.match(operation_id):
                # 非预期文件：不纳入恢复，也不删除业务数据
                continue
            try:
                data = self._read_json(os.path.join(base, name))
            except ValueError:
                # JSON 不可解析（原子写使正常流程不会出现，仅外部损坏）
                data = None
            result.append((operation_id, data if isinstance(data, dict) else None))
        return sorted(result, key=lambda item: item[0])

    # ---- 份额文件与钱包元数据（轮换激活用）--------------------------------

    def save_share(self, wallet_id: str, record: dict) -> None:
        """原子地写入（或覆盖）一个份额文件（含该份额私钥 hex）。"""
        path = self._share_path(wallet_id, record["share_id"])
        with self._lock:
            self._atomic_write(path, record)

    def delete_share(self, wallet_id: str, share_id: str) -> None:
        """删除一个份额文件（轮换激活换下旧份额 / 回滚清理新份额用）。"""
        path = self._share_path(wallet_id, share_id)
        with self._lock:
            try:
                os.unlink(path)
            except FileNotFoundError:
                pass

    def list_share_files(self, wallet_id: str) -> list[str]:
        """列出 shares/<wallet_id>/ 目录内全部份额文件对应的 share_id
        （仅纳入形如 <合法 share_id>.json 的正式文件，忽略临时残留）。"""
        base = os.path.join(self._shares_dir, wallet_id)
        try:
            names = os.listdir(base)
        except (FileNotFoundError, NotADirectoryError):
            return []
        result = []
        for name in names:
            if not name.endswith(".json"):
                continue
            share_id = name[: -len(".json")]
            if _SAFE_SHARE_ID.match(share_id):
                result.append(share_id)
        return sorted(result)

    def save_wallet_meta(self, wallet_id: str, meta: dict) -> None:
        """原子地覆盖钱包元数据文件（无私钥；轮换激活/回滚用）。"""
        path = self._wallet_path(wallet_id)
        with self._lock:
            self._atomic_write(path, meta)

    # ---- 份额轮换记录 -----------------------------------------------------

    def _rotations_path(self, wallet_id: str) -> str:
        _check_id("wallet_id", wallet_id)
        return os.path.join(self._rotations_dir, wallet_id + ".json")

    def create_rotation(
        self, wallet_id: str, rotation_id: str, record: dict
    ) -> Optional[dict]:
        """原子地创建一条份额轮换记录。

        在同一把锁内先查重：若该 rotation_id 已存在，则不覆盖、
        直接返回已有记录；否则写入并返回 None。
        """
        _check_id("rotation_id", rotation_id)
        path = self._rotations_path(wallet_id)
        with self._lock:
            all_records = self._read_json(path) or {}
            existing = all_records.get(rotation_id)
            if existing is not None:
                return existing
            all_records[rotation_id] = record
            self._atomic_write(path, all_records)
            return None

    def get_rotation(
        self, wallet_id: str, rotation_id: str
    ) -> Optional[dict]:
        """返回某条份额轮换记录，不存在返回 None。"""
        _check_id("rotation_id", rotation_id)
        all_records = self._read_json(self._rotations_path(wallet_id))
        if not all_records:
            return None
        return all_records.get(rotation_id)

    def list_rotations(self, wallet_id: str) -> list[dict]:
        """返回该钱包的全部份额轮换记录（无文件时返回 []）。"""
        _check_id("wallet_id", wallet_id)
        all_records = self._read_json(self._rotations_path(wallet_id))
        if not all_records:
            return []
        return [
            dict(record)
            for record in all_records.values()
            if isinstance(record, dict)
        ]

    def update_rotation(
        self, wallet_id: str, rotation_id: str, record: dict
    ) -> None:
        """原子地覆盖一条已存在的份额轮换记录（状态机推进用）。"""
        _check_id("rotation_id", rotation_id)
        path = self._rotations_path(wallet_id)
        with self._lock:
            all_records = self._read_json(path) or {}
            all_records[rotation_id] = record
            self._atomic_write(path, all_records)

    def delete_rotation(self, wallet_id: str, rotation_id: str) -> None:
        """删除一条份额轮换记录（准备事件追加失败时回滚用）。"""
        _check_id("rotation_id", rotation_id)
        path = self._rotations_path(wallet_id)
        with self._lock:
            all_records = self._read_json(path)
            if not all_records or rotation_id not in all_records:
                return
            del all_records[rotation_id]
            if all_records:
                self._atomic_write(path, all_records)
            else:
                try:
                    os.unlink(path)
                except FileNotFoundError:
                    pass

    # ---- 轮换暂存目录（新份额私钥 + 激活备份）------------------------------

    def _staging_dir(self, wallet_id: str, rotation_id: str) -> str:
        _check_id("wallet_id", wallet_id)
        _check_id("rotation_id", rotation_id)
        return os.path.join(
            self._rotation_staging_dir, wallet_id, rotation_id
        )

    def _staging_share_path(
        self, wallet_id: str, rotation_id: str, share_id: str
    ) -> str:
        _check_share_id(share_id)
        return os.path.join(
            self._staging_dir(wallet_id, rotation_id), share_id + ".json"
        )

    def _staging_backup_path(
        self, wallet_id: str, rotation_id: str, share_id: str
    ) -> str:
        _check_share_id(share_id)
        return os.path.join(
            self._staging_dir(wallet_id, rotation_id),
            share_id + ".bak.json",
        )

    def _staging_wallet_backup_path(
        self, wallet_id: str, rotation_id: str
    ) -> str:
        return os.path.join(
            self._staging_dir(wallet_id, rotation_id), "wallet.bak.json"
        )

    def save_staging_share(
        self, wallet_id: str, rotation_id: str, record: dict
    ) -> None:
        """把一个新份额（含私钥）写入轮换暂存目录，一份一个文件。"""
        path = self._staging_share_path(
            wallet_id, rotation_id, record["share_id"]
        )
        with self._lock:
            self._atomic_write(path, record)

    def get_staging_share(
        self, wallet_id: str, rotation_id: str, share_id: str
    ) -> Optional[dict]:
        """返回暂存的新份额记录，不存在返回 None。"""
        return self._read_json(
            self._staging_share_path(wallet_id, rotation_id, share_id)
        )

    def save_activation_backups(
        self,
        wallet_id: str,
        rotation_id: str,
        old_shares: list[dict],
        wallet_meta: dict,
    ) -> None:
        """激活前把旧份额文件与钱包元数据备份进暂存目录（回滚依据）。"""
        with self._lock:
            for record in old_shares:
                self._atomic_write(
                    self._staging_backup_path(
                        wallet_id, rotation_id, record["share_id"]
                    ),
                    record,
                )
            self._atomic_write(
                self._staging_wallet_backup_path(wallet_id, rotation_id),
                wallet_meta,
            )

    def delete_activation_backups(
        self, wallet_id: str, rotation_id: str
    ) -> None:
        """删除激活备份（*.bak.json），保留暂存的新份额文件。"""
        staging = self._staging_dir(wallet_id, rotation_id)
        with self._lock:
            try:
                names = os.listdir(staging)
            except FileNotFoundError:
                return
            for name in names:
                if name.endswith(".bak.json"):
                    try:
                        os.unlink(os.path.join(staging, name))
                    except FileNotFoundError:
                        pass

    def delete_staging(self, wallet_id: str, rotation_id: str) -> None:
        """删除整个轮换暂存目录（激活成功后清理暂存与备份）。"""
        staging = self._staging_dir(wallet_id, rotation_id)
        with self._lock:
            shutil.rmtree(staging, ignore_errors=True)

    # ---- 启动恢复：未完成的激活先回滚，轮换残留按有效性判定 --------------

    def list_rotation_wallet_ids(self) -> list[str]:
        """返回拥有轮换记录文件的全部 wallet_id。

        只纳入匹配安全 id 的正式记录文件，忽略原子写残留的
        ``.tmp-*.json`` 等临时文件，避免把临时文件名当成 wallet_id。
        """
        try:
            names = os.listdir(self._rotations_dir)
        except FileNotFoundError:
            return []
        return sorted(
            name[: -len(".json")]
            for name in names
            if name.endswith(".json")
            and _SAFE_ID.match(name[: -len(".json")])
        )

    def list_staging_wallet_ids(self) -> list[str]:
        """返回轮换暂存根目录下出现过的全部 wallet_id（含无记录文件的）。
        只纳入匹配安全 id 的目录名，忽略任何杂项目录。"""
        try:
            names = os.listdir(self._rotation_staging_dir)
        except FileNotFoundError:
            return []
        return sorted(
            name
            for name in names
            if _SAFE_ID.match(name)
            and os.path.isdir(os.path.join(self._rotation_staging_dir, name))
        )

    def list_staging_rotation_ids(self, wallet_id: str) -> list[str]:
        """返回某钱包暂存目录下的全部 rotation_id 目录名。"""
        _check_id("wallet_id", wallet_id)
        base = os.path.join(self._rotation_staging_dir, wallet_id)
        try:
            names = os.listdir(base)
        except (FileNotFoundError, NotADirectoryError):
            return []
        return sorted(
            name
            for name in names
            if _SAFE_ID.match(name)
            and os.path.isdir(os.path.join(base, name))
        )

    def list_rotation_entries(self, wallet_id: str) -> list[tuple[str, dict]]:
        """返回 (记录键, 记录) 对；记录键即删除时使用的 rotation_id。"""
        _check_id("wallet_id", wallet_id)
        all_records = self._read_json(self._rotations_path(wallet_id))
        if not isinstance(all_records, dict):
            return []
        return [
            (key, record)
            for key, record in all_records.items()
            if isinstance(key, str) and isinstance(record, dict)
        ]

    def rollback_activation_files(
        self, wallet_id: str, rotation_record: dict
    ) -> None:
        """用暂存目录中的备份恢复钱包元数据与旧份额文件，并删除已换入的
        新份额文件。备份缺失（崩溃发生在备份写入前）时各步自动跳过。"""
        rotation_id = rotation_record["rotation_id"]
        wallet_backup = self._read_json(
            self._staging_wallet_backup_path(wallet_id, rotation_id)
        )
        if wallet_backup is not None:
            self.save_wallet_meta(wallet_id, wallet_backup)
        staging = self._staging_dir(wallet_id, rotation_id)
        try:
            names = os.listdir(staging)
        except FileNotFoundError:
            names = []
        for name in names:
            if name.endswith(".bak.json") and name != "wallet.bak.json":
                share_record = self._read_json(os.path.join(staging, name))
                if isinstance(share_record, dict) and isinstance(
                    share_record.get("share_id"), str
                ):
                    self.save_share(wallet_id, share_record)
        for share_id in rotation_record.get("share_ids", []):
            if isinstance(share_id, str):
                self.delete_share(wallet_id, share_id)

    @staticmethod
    def _rotation_record_shape_ok(record: dict) -> bool:
        """轮换记录的基本形状校验（启动恢复判定"无效记录"用）。"""
        rotation_id = record.get("rotation_id")
        if not isinstance(rotation_id, str) or not _SAFE_ID.match(rotation_id):
            return False
        if record.get("state") not in ("prepared", "activating", "active"):
            return False
        share_ids = record.get("share_ids")
        if (
            not isinstance(share_ids, list)
            or len(share_ids) != 2
            or len(set(share_ids)) != 2
            or any(
                not isinstance(sid, str) or not _SAFE_SHARE_ID.match(sid)
                for sid in share_ids
            )
        ):
            return False
        public_key = record.get("public_key")
        if not isinstance(public_key, str):
            return False
        try:
            if len(bytes.fromhex(public_key)) != 64:
                return False
        except ValueError:
            return False
        # previous_public_key 仅 activating/active 携带；一旦存在必须是
        # 64 字节公钥 hex（链对账用），形状非法即不可对账。
        previous = record.get("previous_public_key")
        if previous is not None:
            if not isinstance(previous, str):
                return False
            try:
                if len(bytes.fromhex(previous)) != 64:
                    return False
            except ValueError:
                return False
        created_at = record.get("created_at")
        if created_at is not None and not isinstance(created_at, str):
            return False
        return True

    def _prepared_staging_valid(self, wallet_id: str, record: dict) -> bool:
        """判定 prepared 轮换的暂存目录是否完整有效。

        仅当全部满足时保留：目录名与 rotation_id 一致（由路径构造保证）、
        目录内恰有记录中两个 share_ids 对应的份额文件（无多无缺）、每个
        文件 JSON 可解析、share_id 与记录一致、public_key 恰为 32 字节、
        私钥恰为 32 字节且能推导出该 public_key、两个份额公钥按序拼接
        等于记录中的钱包 public_key。
        """
        rotation_id = record["rotation_id"]
        share_ids = list(record["share_ids"])
        staging = self._staging_dir(wallet_id, rotation_id)
        try:
            names = set(os.listdir(staging))
        except (FileNotFoundError, NotADirectoryError):
            return False
        if names != {sid + ".json" for sid in share_ids}:
            return False
        share_public_keys: list[bytes] = []
        for share_id in share_ids:
            try:
                data = self._read_json(
                    os.path.join(staging, share_id + ".json")
                )
            except (ValueError, OSError):
                # JSON 不可解析 / 读取失败
                return False
            if not isinstance(data, dict) or data.get("share_id") != share_id:
                return False
            public_hex = data.get("public_key")
            private_hex = data.get("private_key")
            if not isinstance(public_hex, str) or not isinstance(
                private_hex, str
            ):
                return False
            try:
                public_bytes = bytes.fromhex(public_hex)
                private_bytes = bytes.fromhex(private_hex)
            except ValueError:
                return False
            if len(public_bytes) != 32 or len(private_bytes) != 32:
                return False
            try:
                if public_key_from_private(private_bytes) != public_bytes:
                    return False
            except ValueError:
                return False
            share_public_keys.append(public_bytes)
        return (
            combine_public_keys(share_public_keys).hex()
            == record["public_key"]
        )

    def _load_backup_wallet_meta(
        self, wallet_id: str, rotation_id: str
    ) -> Optional[dict]:
        return self._read_json(
            self._staging_wallet_backup_path(wallet_id, rotation_id)
        )

    def _assert_rollback_possible(
        self,
        wallet_id: str,
        record: dict,
        expected_previous: Optional[str] = None,
    ) -> None:
        """事件未落盘的激活回滚前，确认能安全恢复旧钱包与旧份额。

        - 钱包元数据仍指向旧公钥（换入尚未发生）：只要当前元数据里的
          旧份额文件都还在即可，换入的新份额会在回滚时删除，无需备份；
        - 元数据已指向新公钥（换入已发生）：必须有激活前的钱包/份额
          备份作为权威回滚依据；
        - 元数据旧但旧份额缺失：同样必须有备份。
        expected_preversed 为审计激活链中该轮换的前一轮在用公钥（无激活
        历史时为 None）：记录自报的 previous_public_key 必须与之相容，
        否则属于跨轮次不相容现场，fail-closed。无法安全恢复时抛
        RecoveryError，绝不猜写旧密钥。
        """
        rotation_id = record["rotation_id"]
        current = self.get_wallet(wallet_id)
        if not isinstance(current, dict):
            raise RecoveryError(
                f"wallet {wallet_id!r} metadata missing during rollback"
            )
        backup_meta = self._load_backup_wallet_meta(wallet_id, rotation_id)
        recorded_previous = record.get("previous_public_key")
        # 记录/备份/链上的 previous 必须互相一致
        authoritative_previous = expected_previous
        if isinstance(backup_meta, dict) and isinstance(
            backup_meta.get("public_key"), str
        ):
            backup_previous = backup_meta["public_key"]
            if authoritative_previous is None:
                authoritative_previous = backup_previous
            elif backup_previous != authoritative_previous:
                raise RecoveryError(
                    f"wallet {wallet_id!r} rotation {rotation_id!r} backup "
                    "public_key is incompatible with the rotation chain"
                )
        if isinstance(recorded_previous, str):
            if authoritative_previous is None:
                authoritative_previous = recorded_previous
            elif recorded_previous != authoritative_previous:
                raise RecoveryError(
                    f"wallet {wallet_id!r} rotation {rotation_id!r} "
                    "previous_public_key is incompatible with the rotation chain"
                )
        if authoritative_previous is not None:
            if current.get("public_key") not in (
                record["public_key"],
                authoritative_previous,
            ):
                # 当前钱包公钥既不是本轮目标、也不是上一轮在用公钥：
                # 属于跨轮次不相容现场，无法判断该回到哪里，fail-closed。
                raise RecoveryError(
                    f"wallet {wallet_id!r} rotation {rotation_id!r} current "
                    "public_key matches neither this nor the previous rotation"
                )

        swapped = current.get("public_key") == record["public_key"]
        if swapped:
            if backup_meta is None:
                raise RecoveryError(
                    f"wallet {wallet_id!r} rotation {rotation_id!r} "
                    "has no activation backup to roll back"
                )
            return
        # 元数据仍旧：旧份额必须完整，否则需备份才能恢复
        shares = current.get("shares")
        old_ids = [
            s.get("share_id")
            for s in shares
            if isinstance(s, dict)
            and s.get("share_id") not in record["share_ids"]
        ] if isinstance(shares, list) else []
        missing = [
            sid
            for sid in old_ids
            if isinstance(sid, str) and self.get_share(wallet_id, sid) is None
        ]
        if missing and backup_meta is None:
            raise RecoveryError(
                f"wallet {wallet_id!r} rotation {rotation_id!r} lost "
                f"in-use shares {missing!r} without backup"
            )

    def _rollback_incomplete_activation(
        self, wallet_id: str, record: dict
    ) -> dict:
        """事件未落盘的激活：回滚旧钱包元数据与旧份额、删除已换入的
        新份额，状态置回 prepared，并清掉激活备份、保留经校验的暂存份额。
        返回置回 prepared 的记录。"""
        self.rollback_activation_files(wallet_id, record)
        rotation_id = record["rotation_id"]
        restored = {
            k: v
            for k, v in record.items()
            if k != "previous_public_key"
        }
        restored["state"] = "prepared"
        self.update_rotation(wallet_id, rotation_id, restored)
        self.delete_activation_backups(wallet_id, rotation_id)
        return restored

    @staticmethod
    def _validated_share_record(
        rotation_id: str, share_id: str, staged: object
    ) -> dict:
        """逐份密码学校验一份新份额：形状/hex/长度/私钥推导公钥必须一致。
        通过返回记录，否则抛 RecoveryError，绝不猜写密钥。"""
        if not isinstance(staged, dict) or staged.get("share_id") != share_id:
            raise RecoveryError(
                f"rotation {rotation_id!r} missing new share {share_id!r}"
            )
        public_hex = staged.get("public_key")
        private_hex = staged.get("private_key")
        if not isinstance(public_hex, str) or not isinstance(private_hex, str):
            raise RecoveryError(
                f"rotation {rotation_id!r} malformed new share"
            )
        try:
            public_bytes = bytes.fromhex(public_hex)
            private_bytes = bytes.fromhex(private_hex)
        except ValueError:
            raise RecoveryError(
                f"rotation {rotation_id!r} non-hex new share"

        )
    if len(public_bytes) != 32 or len(private_bytes) != 32:
        raise RecoveryError(
            f"rotation {rotation_id!r} bad-length new share"
        )
    try:
        if public_key_from_private(private_bytes) != public_bytes:
            raise RecoveryError(
                f"rotation {rotation_id!r} new share key mismatch"
            )
    except ValueError:
        raise RecoveryError(
            f"rotation {rotation_id!r} invalid new share private key"
        )
    return staged

def _build_activation_chain(
    self,
    wallet_id: str,
    activated: dict[str, dict],
    records_by_rid: dict[str, dict],
) -> list[tuple[int, str, dict]]:
    """按审计 seq 建立已提交激活链 ``[(seq, rotation_id, event)]``。

    拒绝缺失（有激活事件无记录）、重复（同 seq/同公钥/跨轮次份额
    重叠）、乱序（previous_public_key 接不上上一轮 public_key、首项
    前驱指向任一轮在用公钥）、以及事件与记录的 share_ids/public_key/
    previous_public_key 不相容。任一矛盾抛 RecoveryError（fail-closed）。
    """
    ordered = sorted(
        activated.values(), key=lambda event: event.get("seq", 0)
    )
    all_pubkeys = {
        d.get("public_key")
        for d in (
            e.get("details") for e in ordered if isinstance(e.get("details"), dict)
        )
    }
    chain: list[tuple[int, str, dict]] = []
    seen_pubkeys: set[str] = set()
    seen_share_ids: set[str] = set()
    previous_pubkey: Optional[str] = None
    last_seq = 0
    for event in ordered:
        seq = event.get("seq")
        if (
            not isinstance(seq, int)
            or isinstance(seq, bool)
            or seq <= last_seq
        ):
            raise RecoveryError(
                f"wallet {wallet_id!r} rotation activation events have a "
                "missing, duplicated or out-of-order seq"
            )
        last_seq = seq
        details = event.get("details")
        if not isinstance(details, dict):
            raise RecoveryError(
                f"wallet {wallet_id!r} rotation activation event {seq!r} "
                "has no object details"
            )
        rid = details.get("rotation_id")
        share_ids = details.get("share_ids")
        public_key = details.get("public_key")
        prev_key = details.get("previous_public_key")
        if (
            not isinstance(rid, str)
            or not _SAFE_ID.match(rid)
            or not isinstance(share_ids, list)
            or len(share_ids) != 2
            or len(set(share_ids)) != 2
            or any(
                not isinstance(sid, str) or not _SAFE_SHARE_ID.match(sid)
                for sid in share_ids
            )
            or not isinstance(public_key, str)
            or not isinstance(prev_key, str)
        ):
            raise RecoveryError(
                f"wallet {wallet_id!r} rotation activation event {seq!r} "
                "is malformed"
            )
        try:
            if len(bytes.fromhex(public_key)) != 64 or len(
                bytes.fromhex(prev_key)
            ) != 64:
                raise ValueError
        except ValueError:
            raise RecoveryError(
                f"wallet {wallet_id!r} rotation activation event {seq!r} "
                "has a bad-length public key"
            )
        record = records_by_rid.get(rid)
        if record is None:
            # 提交点事件存在却没有轮换记录：缺失，拒绝猜写
            raise RecoveryError(
                f"wallet {wallet_id!r} has a committed activation for "
                f"{rid!r} but no rotation record"
            )
        if record["public_key"] != public_key or list(
            record["share_ids"]
        ) != list(share_ids):
            raise RecoveryError(
                f"wallet {wallet_id!r} rotation {rid!r} record is "
                "inconsistent with its activated event"
            )
        record_previous = record.get("previous_public_key")
        if (
            isinstance(record_previous, str)
            and record_previous != prev_key
        ):
            raise RecoveryError(
                f"wallet {wallet_id!r} rotation {rid!r} "
                "previous_public_key disagrees with its activated event"
            )
        if public_key == prev_key:
            raise RecoveryError(
                f"wallet {wallet_id!r} rotation {rid!r} does not change "
                "the wallet public key"
            )
        if previous_pubkey is not None and prev_key != previous_pubkey:
            # 乱序/跨轮次不相容：本轮的 previous 必须恰为上一轮在用公钥
            raise RecoveryError(
                f"wallet {wallet_id!r} rotation {rid!r} previous_public_key "
                "does not extend the prior rotation"
            )
        if previous_pubkey is None and prev_key in all_pubkeys:
            # 首项的前驱指向某一轮在用公钥：链被截断或乱序
            raise RecoveryError(
                f"wallet {wallet_id!r} rotation {rid!r} chains from another "
                "rotation public key, the chain is incomplete"
            )
        if public_key in seen_pubkeys:
            raise RecoveryError(
                f"wallet {wallet_id!r} rotation {rid!r} repeats a public key"
            )
        overlap = seen_share_ids.intersection(share_ids)
        if overlap:
            raise RecoveryError(
                f"wallet {wallet_id!r} rotation {rid!r} reuses shares "
                f"{sorted(overlap)!r} from an earlier rotation"
            )
        seen_pubkeys.add(public_key)
        seen_share_ids.update(share_ids)
        chain.append((seq, rid, event))
        previous_pubkey = public_key
    return chain

def _roll_forward_to_tail(
    self,
    wallet_id: str,
    chain: list[tuple[int, str, dict]],
    records_by_rid: dict[str, dict],
) -> None:
    """把磁盘现场前滚为激活链链顶（最后一次已提交激活）的唯一结果。

    只有链顶需要对账磁盘份额/钱包元数据：更早的历史激活只把记录校准
    为 active 并清理其暂存私钥残留，绝不重放它们的换入（否则会向后一
    轮已合法删除的份额索要密钥、或把旧公钥写回钱包）。前滚逐份做密码
    学校验，缺份额/对不上时抛 RecoveryError，绝不猜写密钥。
    """
    # 所有已提交激活的记录都校准为 active，previous_public_key 以
    # 提交点事件为准（补齐崩溃窗口里停在 activating/缺字段的记录）。
    for _seq, rid, event in chain:
        record = records_by_rid[rid]
        details = event["details"]
        correct = dict(record)
        correct["state"] = "active"
        correct["share_ids"] = list(details["share_ids"])
        correct["public_key"] = details["public_key"]
        correct["previous_public_key"] = details["previous_public_key"]
        if correct != record:
            self.update_rotation(wallet_id, rid, correct)

    if not chain:
        return
    _tail_seq, tail_rid, tail_event = chain[-1]
    tail_details = tail_event["details"]
    tail_share_ids = list(tail_details["share_ids"])
    tail_public_key = tail_details["public_key"]

    # 链顶两份新份额：在用目录优先，崩溃窗口可能仍在暂存目录。
    tail_share_records: list[dict] = []
    for share_id in tail_share_ids:
        staged = self.get_share(wallet_id, share_id)
        if staged is None:
            staged = self.get_staging_share(
                wallet_id, tail_rid, share_id
            )
        tail_share_records.append(
            self._validated_share_record(tail_rid, share_id, staged)
        )
    new_public_keys = [
        bytes.fromhex(r["public_key"]) for r in tail_share_records
    ]
    if combine_public_keys(new_public_keys).hex() != tail_public_key:
        raise RecoveryError(
            f"rotation {tail_rid!r} new shares do not match the "
            "committed public key"
        )

    current_meta = self.get_wallet(wallet_id)
    backup_meta = self._read_json(
        self._staging_wallet_backup_path(wallet_id, tail_rid)
    )

    def meta_matches(meta: object) -> bool:
        if not isinstance(meta, dict):
            return False
        if meta.get("public_key") != tail_public_key:
            return False
        entries = meta.get("shares")
        if not isinstance(entries, list) or len(entries) != 2:
            return False
        halves = (
            bytes.fromhex(tail_public_key)[:32].hex(),
            bytes.fromhex(tail_public_key)[32:].hex(),
        )
        for index, entry in enumerate(entries):
            if not isinstance(entry, dict):
                return False
            if entry.get("share_id") != tail_share_ids[index]:
                return False
            if entry.get("public_key") != halves[index]:
                return False
        return True

    if not meta_matches(current_meta):
        base_meta = current_meta if isinstance(current_meta, dict) else backup_meta
        if not isinstance(base_meta, dict):
            raise RecoveryError(
                f"wallet {wallet_id!r} metadata missing during roll-forward"
            )
        new_meta = dict(base_meta)
        new_meta["wallet_id"] = wallet_id
        new_meta["shares"] = [
            {"share_id": r["share_id"], "public_key": r["public_key"]}
            for r in tail_share_records
        ]
        new_meta["public_key"] = tail_public_key
        self.save_wallet_meta(wallet_id, new_meta)

    # 链顶份额逐份落盘；shares/ 目录最终只能剩链顶两份（清掉创世及
    # 历史各轮残留，也清掉崩溃窗口换入到一半的杂份）。会话参与者替换
    # 份额（*-share）不属于轮换现场，由签名会话恢复对账，这里豁免。
    for share_record in tail_share_records:
        self.save_share(wallet_id, share_record)
    tail_set = set(tail_share_ids)
    for share_id in self.list_share_files(wallet_id):
        if share_id not in tail_set and not _is_replacement_share_id(
            share_id
        ):
            self.delete_share(wallet_id, share_id)

    # 已提交各轮的暂存私钥/备份残留全部清干净（历史轮一般已无目录）。
    for _seq, rid, _event in chain:
        self.delete_staging(wallet_id, rid)

def forward_complete_activation(
    self, wallet_id: str, record: dict, event: dict
) -> None:
    """share_rotation_activated 事件已落盘后的前滚入口（激活事务
    异常分支与恢复共用）。

    不孤立地只处理本轮：而是按审计中的全部已提交激活事件重建链，
    把磁盘对账到真正的链顶，并校验链连续/事件与记录一致。这样连续
    多轮轮换后，任一轮换的异常收尾都不会把历史轮误当未完成轮换重做。
    缺新份额或现场自相矛盾时抛 RecoveryError（fail-closed）。"""
    from .audit import AuditStore

    audit_store = AuditStore(self.data_dir)
    activated = audit_store.activated_rotation_events(wallet_id)
    prepared = audit_store.prepared_rotation_events(wallet_id)
    # 调用方持锁且传入的事件必定已落盘；防御性确保它在链映射中。
    details = event.get("details")
    rid = details.get("rotation_id") if isinstance(details, dict) else None
    if isinstance(rid, str):
        activated.setdefault(rid, event)
    self.recover_wallet_rotation(wallet_id, activated, prepared)

def verify_rotation_scene_consistent(
    self,
    wallet_id: str,
    activated: dict[str, dict],
    prepared: dict[str, dict],
) -> bool:
    """只读判定轮换现场是否静止且与激活链一致（不写盘、不清理）。

    常驻请求的自愈快路径用它在"看似静止"时仍做一次链对账：任一已
    提交激活缺记录、链乱序/跨轮次不相容、链顶公钥/份额与钱包元数据或
    磁盘份额不符、仍有暂存/备份残留，都返回 False，由调用方走完整
    恢复（恢复会在真正矛盾时 fail-closed）。现场完全静止才返回 True。
    """
    try:
        entries = self.list_rotation_entries(wallet_id)
        records_by_rid: dict[str, dict] = {}
        for _key, record in entries:
            rid = record.get("rotation_id")
            if not self._rotation_record_shape_ok(record):
                return False
            rid = record["rotation_id"]
            if rid in records_by_rid:
                return False
            records_by_rid[rid] = record
        chain = self._build_activation_chain(
            wallet_id, activated, records_by_rid
        )
        # 有暂存残留（prepared 暂存目录除外）即非静止。这里只判定目录
        # 是否存在（每请求快路径不做暂存份额密码学重验；完整密码学
        # 校验仍由启动恢复/激活事务路径负责）。
        kept_prepared = {
            rid
            for rid, record in records_by_rid.items()
            if rid not in activated
            and record["state"] == "prepared"
            and os.path.isdir(
                self._staging_dir(wallet_id, rid)
            )
        }
        for staging_rid in self.list_staging_rotation_ids(wallet_id):
            if staging_rid not in kept_prepared:
                return False
        # 未提交的 activating/active 记录是崩溃现场
        for rid, record in records_by_rid.items():
            if rid not in activated and record["state"] in (
                "activating",
                "active",
            ):
                return False
        if not chain:
            # 无已提交激活：钱包应为创世份额且份额文件齐
            current = self.get_wallet(wallet_id)
            if not isinstance(current, dict):
                return False
            ids = [
                s.get("share_id")
                for s in current.get("shares", [])
                if isinstance(s, dict)
            ]
            if ids != ["share-1", "share-2"]:
                return False
            return all(
                self.get_share(wallet_id, sid) is not None for sid in ids
            )
        tail = chain[-1][2]["details"]
        tail_pub = tail["public_key"]
        tail_ids = list(tail["share_ids"])
        current = self.get_wallet(wallet_id)
        if not isinstance(current, dict):
            return False
        if current.get("public_key") != tail_pub:
            return False
        ids = [
            s.get("share_id")
            for s in current.get("shares", [])
            if isinstance(s, dict)
        ]
        if ids != tail_ids:
            return False
        # shares/ 目录只能有链顶两份，且逐份与链顶公钥密码学一致；
        # 会话参与者替换份额（*-share）由签名会话恢复对账，这里豁免。
        on_disk_shares = set(self.list_share_files(wallet_id))
        if not set(tail_ids) <= on_disk_shares:
            return False
        if any(
            not _is_replacement_share_id(sid)
            for sid in on_disk_shares - set(tail_ids)
        ):
            return False
        halves = (
            bytes.fromhex(tail_pub)[:32],
            bytes.fromhex(tail_pub)[32:],
        )
        for index, sid in enumerate(tail_ids):
            share = self.get_share(wallet_id, sid)
            if not isinstance(share, dict):
                return False
            try:
                priv = bytes.fromhex(share.get("private_key", ""))
                pub = bytes.fromhex(share.get("public_key", ""))
            except ValueError:
                return False
            if len(priv) != 32 or pub != halves[index]:
                return False
            if public_key_from_private(priv) != pub:
                return False
        # 各已提交 active 记录的字段必须与事件一致
        for _seq, rid, event in chain:
            record = records_by_rid[rid]
            d = event["details"]
            if record["state"] != "active":
                return False
            if record["public_key"] != d["public_key"]:
                return False
            if list(record["share_ids"]) != list(d["share_ids"]):
                return False
            if record.get("previous_public_key") != d[
                "previous_public_key"
            ]:
                return False
        return True
    except (RecoveryError, OSError, ValueError):
        return False

def recover_wallet_rotation(
    self,
    wallet_id: str,
    activated: Optional[dict[str, dict]] = None,
    prepared: Optional[dict[str, dict]] = None,
) -> None:
    """按钱包恢复轮换现场（调用方须持有该钱包的跨进程事务锁）。

    先按审计 seq 建立连续的已提交激活公钥/份额时间线，再分三类对账：

    - 已提交激活（share_rotation_activated 事件在）：链上各轮记录校准
      为 active，磁盘份额/钱包公钥只前滚到**链顶**一轮并清理全部暂存/
      备份；历史轮不再触碰在用份额。链缺失/重复/乱序/跨轮次不相容/
      事件与记录不一致一律 RecoveryError（fail-closed），绝不猜写；
    - 事件未落盘的 activating/active（含状态已写 active）：恢复上一轮
      完整份额与公钥、置回 prepared，保留经校验有效的暂存份额；缺
      回滚备份或与激活链不相容时 fail-closed；
    - prepared：暂存经密码学校验通过才保留，否则连记录带暂存删除；
      若该轮存在 share_rotation_prepared 事件，其 share_ids/public_key
      必须与记录一致，否则 fail-closed；
    - 形状无效且**无**激活事件的记录、无记录的孤儿暂存：安全删除。

    全程不新增审计事件、不分配 seq；被删除暂存私钥不留副本。
    """
    _check_id("wallet_id", wallet_id)
    activated = activated or {}
    prepared = prepared or {}

    entries = self.list_rotation_entries(wallet_id)
    records_by_rid: dict[str, dict] = {}
    for key, record in entries:
        rid = record.get("rotation_id")
        if not self._rotation_record_shape_ok(record):
            # 形状无效：若该轮已有激活提交点则属"事件与记录不一致"，
            # 绝不能删除提交记录掩盖矛盾，直接 fail-closed。
            if isinstance(rid, str) and rid in activated:
                raise RecoveryError(
                    f"wallet {wallet_id!r} rotation {rid!r} is committed "
                    "but its record is malformed"
                )
            self.delete_rotation(wallet_id, key)
            if isinstance(rid, str) and _SAFE_ID.match(rid):
                self.delete_staging(wallet_id, rid)
            continue
        rid = record["rotation_id"]
        if rid in records_by_rid:
            # 同一 rotation_id 出现两条记录：重复，拒绝猜测保留哪条
            raise RecoveryError(
                f"wallet {wallet_id!r} has duplicate rotation records for "
                f"{rid!r}"
            )
        records_by_rid[rid] = record

    # 提交点事件在却没有任何记录（缺失）：链构建内统一 fail-closed。
    chain = self._build_activation_chain(
        wallet_id, activated, records_by_rid
    )
    chain_tail_public = (
        chain[-1][2]["details"]["public_key"] if chain else None
    )

    kept_prepared: set[str] = set()
    for rid, record in records_by_rid.items():
        if rid in activated:
            # 已提交轮：磁盘对账统一在链顶前滚中处理，这里不动。
            continue
        if record["state"] in ("activating", "active"):
            # 激活状态已写但提交点事件未落盘：提交未生效，恢复上一轮
            # 完整份额与公钥、置回 prepared，保留有效暂存。
            self._assert_rollback_possible(
                wallet_id, record, chain_tail_public
            )
            record = self._rollback_incomplete_activation(
                wallet_id, record
            )
        # prepared（含刚回滚的）：暂存经密码学校验通过才保留。
        if not self._prepared_staging_valid(wallet_id, record):
            # 暂存缺失/损坏/不匹配：记录与残留一起安全删除，绝不留下
            # 来路不明的私钥副本（此轮无激活事件，删除不丢已提交状态）。
            self.delete_rotation(wallet_id, rid)
            self.delete_staging(wallet_id, rid)
            continue
        # 有 prepared 事件时，事件与记录必须一致；不一致 fail-closed，
        # 绝不带着矛盾现场继续服务。
        prepared_event = prepared.get(rid)
        if prepared_event is not None:
            details = prepared_event.get("details")
            if (
                not isinstance(details, dict)
                or details.get("public_key") != record["public_key"]
                or list(details.get("share_ids") or [])
                != list(record["share_ids"])
            ):
                raise RecoveryError(
                    f"wallet {wallet_id!r} rotation {rid!r} record is "
                    "inconsistent with its prepared event"
                )
        kept_prepared.add(rid)

    # 已提交链：校准记录并把磁盘对账到链顶唯一结果。
    self._roll_forward_to_tail(wallet_id, chain, records_by_rid)

    # 孤儿暂存目录：保留中的 prepared 暂存除外，其余（含历史轮遗留）
    # 一律安全删除；已提交轮的暂存已在链顶前滚中清理，此处删除幂等。
    for rotation_id in self.list_staging_rotation_ids(wallet_id):
        if rotation_id not in kept_prepared:
            self.delete_staging(wallet_id, rotation_id)

def recover_incomplete_activations(
    self,
    activated: Optional[dict[str, dict]] = None,
) -> None:
    """启动恢复（无跨进程锁的独立入口；serve 使用 service 层的加锁
    编排）。activated 为各钱包激活事件映射；为 None 时从审计日志读取。
    恢复失败向上抛出 RecoveryError/OSError，由调用方阻止服务就绪。"""
    from .audit import AuditStore

    wallet_ids = sorted(
        set(self.list_rotation_wallet_ids())
        | set(self.list_staging_wallet_ids())
    )
    for wallet_id in wallet_ids:
        audit_store = AuditStore(self.data_dir)
        wallet_activated = activated
        if wallet_activated is None:
            wallet_activated = audit_store.activated_rotation_events(
                wallet_id
            )
        wallet_prepared = audit_store.prepared_rotation_events(wallet_id)
        self.recover_wallet_rotation(
            wallet_id, wallet_activated, wallet_prepared
        )

def _session_view(record: dict) -> dict:
    """签名会话对外视图：原文、状态、已收/缺失份额、到期时间；
    aggregate_signature 仅在 signed 时出现。绝不返回份额签名本身。

    collecting/ready 会话在轮换后由持锁恢复迁移到当前在用快照（旧份额
    已从 shares 剔除），故视图只需按记录的 share_ids 计数。"""
    current_ids = list(record["share_ids"])
    received_set = {entry["share_id"] for entry in record["shares"]}
    received = [sid for sid in current_ids if sid in received_set]
    missing = [sid for sid in current_ids if sid not in received_set]
    view = {
        "id": record["id"],
        "message": record["message"],
        "state": record["state"],
        "received_shares": received,
        "missing_shares": missing,
        "expires_at": record["expires_at"],
    }
    if record["state"] == "signed":
        view["aggregate_signature"] = record["aggregate_signature"]
    return view

@staticmethod
def _validate_session_id(session_id: object) -> None:
    if not isinstance(session_id, str) or not ROTATION_ID_RE.match(
        session_id
    ):
        raise ServiceError(400, "id must match [A-Za-z0-9_-]{1,128}")

@staticmethod
def _validate_session_message(message: object) -> None:
    if not isinstance(message, str) or not message:
        raise ServiceError(400, "message must be a non-empty string")

@staticmethod
def _validate_session_timeout(timeout_seconds: object) -> None:
    # bool 是 int 的子类，必须先排除
    if (
        not isinstance(timeout_seconds, int)
        or isinstance(timeout_seconds, bool)
        or timeout_seconds <= 0
    ):
        raise ServiceError(
            400, "timeout_seconds must be a positive integer"
        )

@staticmethod
def _validate_share_signature(signature_hex: object) -> bytes:
    if not isinstance(signature_hex, str):
        raise ServiceError(400, "signature must be hex")
    try:
        signature = bytes.fromhex(signature_hex)
    except ValueError:
        raise ServiceError(400, "signature must be hex")
    if len(signature) != 64:
        raise ServiceError(
            400, "signature must be a 64-byte Ed25519 signature"
        )
    return signature

# -- 会话历史公钥解析（轮换后恢复重验 / signed 旧份额重放）--------------

def _session_share_public_keys(
    self, wallet_id: str, share_ids: list[str], current_meta: dict
) -> dict[str, str]:
    """收集给定份额 id 对应的份额公钥。

    当前在用份额取自钱包元数据；已轮换失效的旧份额公钥从轮换记录链
    获取（每个轮换记录带其在用时的有序 share_ids 与钱包 public_key），
    确保 signed 会话旧份额同值重放与启动恢复的逐份重验有权威公钥，
    而不是信任请求自报或猜写。

    - 轮换 R 的两份新份额公钥＝R.public_key 的前/后 32 字节，顺序按
      R.share_ids；
    - 最初的 share-1/share-2 公钥＝"创世旧公钥"（任一激活记录的
      previous_public_key 中不等于任何轮换 public_key 的那一个）的
      前/后 32 字节。
    任一份额找不到权威公钥或记录自相矛盾即 fail-closed。
    """
    public: dict[str, str] = {}
    rotations = self._store.list_rotations(wallet_id)
    rotation_pubkeys: set[str] = set()

    def halves(pub_hex: str, where: str) -> tuple[str, str]:
        try:
            raw = bytes.fromhex(pub_hex)
        except ValueError as exc:
            raise RecoveryError(
                f"wallet {wallet_id!r} {where} is not hex"
            ) from exc
        if len(raw) != 64:
            raise RecoveryError(
                f"wallet {wallet_id!r} {where} is not 64 bytes"
            )
        return raw[:32].hex(), raw[32:].hex()

    # 当前在用份额：钱包元数据 shares 有序，公钥两半按其顺序
    current_list = current_meta.get("shares")
    if (
        isinstance(current_list, list)
        and len(current_list) == 2
        and isinstance(current_meta.get("public_key"), str)
    ):
        first, second = halves(
            current_meta["public_key"], "wallet public_key"
        )
        ordered_current = [first, second]
        for index, entry in enumerate(current_list):
            if (
                isinstance(entry, dict)
                and isinstance(entry.get("share_id"), str)
                and isinstance(entry.get("public_key"), str)
                and entry["public_key"] == ordered_current[index]
            ):
                public[entry["share_id"]] = ordered_current[index]
            else:
                raise RecoveryError(
                    f"wallet {wallet_id!r} metadata shares are inconsistent"
                )
    else:
        raise RecoveryError(
            f"wallet {wallet_id!r} metadata is malformed"
        )

    # 各已激活轮换在用时的份额公钥（prepared 未激活的暂存份额绝不能
    # 成为重验依据）
    previous_pubkeys: set[str] = set()
    for rotation in rotations:
        rid = rotation.get("rotation_id")
        rids = rotation.get("share_ids")
        pub_hex = rotation.get("public_key")
        if (
            not isinstance(rid, str)
            or not isinstance(rids, list)
            or len(rids) != 2
            or not all(isinstance(sid, str) for sid in rids)
            or not isinstance(pub_hex, str)
        ):
            raise RecoveryError(
                f"wallet {wallet_id!r} rotation record {rid!r} is malformed"
            )
        if rotation.get("state") != "active":
            # prepared/activating（未提交激活）的份额绝不能成为重验依据
            continue
        rotation_pubkeys.add(pub_hex)
        previous = rotation.get("previous_public_key")
        if isinstance(previous, str):
            previous_pubkeys.add(previous)
        first, second = halves(
            pub_hex, f"rotation {rid!r} public_key"
        )
        public.setdefault(rids[0], first)
        public.setdefault(rids[1], second)

    # 创世旧公钥：previous 链顶端（不等于任何轮换在用公钥）
    genesis_candidates = previous_pubkeys - rotation_pubkeys - {
        current_meta["public_key"]
    }
    if len(genesis_candidates) == 1:
        genesis = next(iter(genesis_candidates))
        first, second = halves(genesis, "genesis previous public_key")
        public.setdefault("share-1", first)
        public.setdefault("share-2", second)
    elif genesis_candidates:
        raise RecoveryError(
            f"wallet {wallet_id!r} has ambiguous rotation history"
        )

    # 会话参与者替换份额（<replacement_id>-share）：公钥的权威来源是
    # 其份额文件（shares/<wallet_id>/<share_id>.json），并做完整密码学
    # 自洽校验；缺失/损坏/矛盾一律 fail-closed。
    for sid in share_ids:
        if sid not in public and REPLACEMENT_SHARE_ID_RE.match(sid):
            public[sid] = self._validated_replacement_share(
                wallet_id, sid
            )["public_key"]

    absent = [sid for sid in share_ids if sid not in public]
    if absent:
        raise RecoveryError(
            f"wallet {wallet_id!r} sign session references shares "
            f"{absent!r} with no resolvable public key"
        )
    return {sid: public[sid] for sid in share_ids}

def _validated_replacement_share(
    self, wallet_id: str, share_id: str
) -> dict:
    """读取并严格校验一份会话参与者替换份额（调用方须持钱包事务锁）。

    份额文件必须恰含 private_key/public_key/share_id 三键，share_id
    与文件名一致，两个 hex 值均为 64 位小写（32 字节），且私钥能推出
    记录的公钥。文件缺失、损坏或任何一项不符都抛 RecoveryError
    （fail-closed，保留现场），绝不猜写密钥。"""
    try:
        share = self._store.get_share(wallet_id, share_id)
    except ValueError as exc:
        raise RecoveryError(
            f"wallet {wallet_id!r} replacement share {share_id!r} is "
            "unreadable"
        ) from exc
    if (
        not isinstance(share, dict)
        or set(share) != {"private_key", "public_key", "share_id"}
        or share.get("share_id") != share_id
    ):
        raise RecoveryError(
            f"wallet {wallet_id!r} replacement share {share_id!r} is "
            "malformed"
        )
    public_hex = share["public_key"]
    private_hex = share["private_key"]
    if not (
        _is_lower_hex_32(public_hex) and _is_lower_hex_32(private_hex)
    ):
        raise RecoveryError(
            f"wallet {wallet_id!r} replacement share {share_id!r} has "
            "malformed key material"
        )
    public_bytes = bytes.fromhex(public_hex)
    private_bytes = bytes.fromhex(private_hex)
    try:
        derived = crypto.public_key_from_private(private_bytes)
    except (ValueError, TypeError) as exc:
        raise RecoveryError(
            f"wallet {wallet_id!r} replacement share {share_id!r} has "
            "an invalid private key"
        ) from exc
    if derived != public_bytes:
        raise RecoveryError(
            f"wallet {wallet_id!r} replacement share {share_id!r} "
            "private/public key mismatch"
        )
    return share

@staticmethod
def _session_expires_at(record: dict):
    return parse_utc_iso(record["expires_at"])

def _session_expire_if_needed(
    self, wallet_id: str, record: dict
) -> dict:
    """懒过期：collecting 与 ready 会话都受 expires_at 约束。

    到点则原子持久化为 expired 并只记一次 action=expired 的
    session_event；投递路径随后返回 409，终态不再聚合。signed/expired
    不再受到期时间影响。调用方须持钱包事务锁。"""
    if record["state"] not in ("collecting", "ready"):
        return record
    expires_at = self._session_expires_at(record)
    if expires_at is None or datetime.now(timezone.utc) < expires_at:
        return record
    expired = dict(record)
    expired["state"] = "expired"
    expired.pop("aggregate_signature", None)
    self._store.update_sign_session(wallet_id, record["id"], expired)
    try:
        self._emit(
            wallet_id,
            self._audit_event(
                audit.TYPE_SESSION_EVENT,
                request_id=record["id"],
                details={"action": "expired", "state": "expired"},
            ),
        )
    except BaseException:
        # 状态/事件原子：事件未落盘恢复原状态
        self._store.update_sign_session(wallet_id, record["id"], record)
        raise
    return expired

def create_sign_session(
    self,
    wallet_id: str,
    session_id: object,
    message: object,
    timeout_seconds: object,
) -> tuple[int, dict]:
    """创建可恢复签名会话，返回 (状态码, 视图)。

    首建 201；同 id 且 message/timeout_seconds 同参重放 200；同 id
    异参 409；参数非法 400；钱包不存在 404。会话状态与 created 事件在
    每钱包跨进程事务锁内原子持久化，事件追加失败回滚会话记录。
    创建重放不触发懒过期。
    """
    record: dict | None = None
    try:
        with self._wallet_lock(wallet_id):
            self._heal_wallet(wallet_id)
            # 404 优先于 400：钱包存在性在锁内先于参数校验
            wallet = self._get_wallet_or_404(wallet_id)
            self._validate_session_id(session_id)
            self._validate_session_message(message)
            self._validate_session_timeout(timeout_seconds)
            existing = self._store.get_sign_session(wallet_id, session_id)
            if existing is not None:
                # 重放前先自愈"会话记录已落盘但 created 事件未落盘"的
                # 他进程创建崩溃残留：按未提交处理，删除后走首次创建。
                if self._audit.find_session_event(
                    wallet_id, session_id, "created"
                ) is None:
                    self._store.delete_sign_session(wallet_id, session_id)
                else:
                    # 同参（message 与 timeout_seconds）重放 200；异参 409。
                    # 原样返回磁盘状态，重放不触发懒过期、不记事件。
                    if (
                        existing["message"] != message
                        or existing["timeout_seconds"] != timeout_seconds
                    ):
                        raise ServiceError(
                            409,
                            f"sign session {session_id!r} already exists "
                            "with different parameters",
                        )
                    return 200, self._session_view(existing)
            now = datetime.now(timezone.utc)
            share_ids = [s["share_id"] for s in wallet["shares"]]
            record = {
                "id": session_id,
                "message": message,
                "timeout_seconds": timeout_seconds,
                "created_at": now.isoformat().replace("+00:00", "Z"),
                "expires_at": (
                    now + timedelta(seconds=timeout_seconds)
                )
                .isoformat()
                .replace("+00:00", "Z"),
                "state": "collecting",
                "share_ids": share_ids,
                "shares": [],
            }
            self._store.create_sign_session(wallet_id, session_id, record)
            try:
                self._emit(
                    wallet_id,
                    self._audit_event(
                        audit.TYPE_SESSION_EVENT,
                        request_id=session_id,
                        details={
                            "action": "created",
                            "message": message,
                            "timeout_seconds": timeout_seconds,
                        },
                    ),
                )
            except BaseException:
                self._store.delete_sign_session(wallet_id, session_id)
                raise
    except CorruptDataError:
        raise
    except ValueError:
        # wallet_id 含非法字符（构造锁路径时抛出）
        raise ServiceError(400, "invalid wallet_id")
    return 201, self._session_view(record)

def get_sign_session(self, wallet_id: str, session_id: str) -> dict:
    """查询会话视图；未知 404。查询时对到点 collecting/ready 会话懒过期。"""
    try:
        with self._wallet_lock(wallet_id):
            self._heal_wallet(wallet_id)
            # 404 优先于 400
            self._get_wallet_or_404(wallet_id)
            self._validate_session_id(session_id)
            record = self._store.get_sign_session(wallet_id, session_id)
            if record is None:
                raise ServiceError(
                    404, f"sign session {session_id!r} not found"
                )
            record = self._session_expire_if_needed(wallet_id, record)
            return self._session_view(record)
    except CorruptDataError:
        raise
    except ValueError:
        raise ServiceError(400, "invalid wallet_id")

@staticmethod
def _session_shares_map(record: dict) -> dict[str, bytes]:
    return {
        entry["share_id"]: bytes.fromhex(entry["signature"])
        for entry in record["shares"]
    }

@staticmethod
def _aggregate_session_shares(record: dict) -> bytes:
    """按会话记录的 share_ids 顺序拼接两份已存份额签名（128 字节）。"""
    received = {
        entry["share_id"]: bytes.fromhex(entry["signature"])
        for entry in record["shares"]
    }
    return crypto.combine_signatures(
        [received[sid] for sid in record["share_ids"]]
    )

def _commit_session_signed(
    self,
    wallet_id: str,
    ready_record: dict,
) -> dict:
    """ready 会话聚合提交：转 signed 并原子记 action=signed 事件。

    审批/hot-cold 门控由调用方在只读校验中完成；本方法只负责会话状态
    与唯一 signed 事件的原子落盘。任一写入失败，以 signed 事件是否真正
    落盘为唯一判据：事件在则前滚补齐为唯一 signed；事件不在则回滚为
    ready（两份份额保留，可重试），并向上抛出。"""
    aggregate = self._aggregate_session_shares(ready_record)
    signed_record = dict(ready_record)
    signed_record["state"] = "signed"
    signed_record["aggregate_signature"] = aggregate.hex()
    try:
        self._store.update_sign_session(
            wallet_id, ready_record["id"], signed_record
        )
        self._emit(
            wallet_id,
            self._audit_event(
                audit.TYPE_SESSION_EVENT,
                request_id=ready_record["id"],
                details={"action": "signed", "state": "signed"},
            ),
        )
    except BaseException:
        landed = self._audit.find_session_event(
            wallet_id, ready_record["id"], "signed"
        )
        if landed is not None:
            # 事件已落盘：前滚补齐，绝不回滚、不重复记事件
            self._store.update_sign_session(
                wallet_id, ready_record["id"], signed_record
            )
            return signed_record
        self._store.update_sign_session(
            wallet_id, ready_record["id"], ready_record
        )
        raise
    return signed_record

def submit_sign_session_share(
    self,
    wallet_id: str,
    session_id: str,
    share_id: object,
    signature_hex: object,
) -> tuple[int, dict]:
    """向会话投递一份额签名，返回 (状态码, 视图)。

    - 首收 201；同份额同值重放 200、异值 409；签名非法/份额已因轮换
      失效或不属于当前在用快照 400；
    - 未知会话 404；expired（含投递时懒过期，collecting 与 ready 均可
      到期）409；
    - 两份齐备转 ready，按既有审批及 hot/cold 门控聚合；门控失败 409
      并保留 ready 供重试（重放在用份额即重试门控）；成功转 signed；
    - 轮换激活后，collecting/ready 会话改用钱包当前两份在用份额：
      已收旧份额在持锁恢复中被剔除，视图只反映当前快照，新份额可继续
      投递；signed 会话冻结创建时快照与聚合结果。
    """
    try:
        return self._submit_sign_session_share_tx(
            wallet_id, session_id, share_id, signature_hex
        )
    except CorruptDataError:
        raise
    except ValueError:
        # wallet_id 含非法字符（构造锁路径时抛出）
        raise ServiceError(400, "invalid wallet_id")

def _submit_sign_session_share_tx(
    self,
    wallet_id: str,
    session_id: str,
    share_id: object,
    signature_hex: object,
) -> tuple[int, dict]:
    with self._wallet_lock(wallet_id):
        self._heal_wallet(wallet_id)
        # 404 优先于 400：锁内先判定钱包存在性
        wallet = self._store.get_wallet(wallet_id)
        if wallet is None:
            raise ServiceError(404, f"wallet {wallet_id!r} not found")
        self._validate_session_id(session_id)
        record = self._store.get_sign_session(wallet_id, session_id)
        if record is None:
            raise ServiceError(
                404, f"sign session {session_id!r} not found"
            )
        # 投递时懒过期：collecting/ready 到点原子转 expired（仅一次事件）
        record = self._session_expire_if_needed(wallet_id, record)
        if record["state"] == "expired":
            # 状态判定优先于载荷校验：已过期一律 409（含畸形载荷）
            raise ServiceError(
                409, f"sign session {session_id!r} has expired"
            )
        state = record["state"]

        # 会话存在且未过期后再校验载荷：share_id 非空、signature 为
        # 64 字节 hex，非法 400
        if not isinstance(share_id, str) or not share_id:
            raise ServiceError(
                400, "share_id must be a non-empty string"
            )
        signature = self._validate_share_signature(signature_hex)

        # collecting/ready 已在 heal 中完成轮换迁移：record.share_ids
        # 即钱包当前在用份额；signed 冻结创建时快照。
        share_pub = {
            s["share_id"]: s["public_key"] for s in wallet["shares"]
        }
        session_ids = list(record["share_ids"])
        # 会话参与者替换份额（<replacement_id>-share）不在钱包元数据
        # 中：其公钥从份额文件解析（heal 已按替换事件对账，缺失/损坏/
        # 矛盾在此 fail-closed 为 503）。
        for sid in session_ids:
            if sid not in share_pub and REPLACEMENT_SHARE_ID_RE.match(
                sid
            ):
                share_pub[sid] = self._validated_replacement_share(
                    wallet_id, sid
                )["public_key"]
        received = self._session_shares_map(record)

        # 已收份额的重放分支必须先于"在用份额"判定：signed 会话冻结
        # 旧快照，轮换后旧份额同值重放仍 200 同体，与既有 /sign 的
        # "已首签请求重放不受轮换影响"一致。
        if share_id in received:
            if signature != received[share_id]:
                raise ServiceError(
                    409,
                    f"share {share_id!r} was already submitted with a "
                    "different signature",
                )
            if state == "ready":
                # ready 上重放在用份额即重试门控/聚合；signed 成功 200，
                # 门控失败 409（ready 保留）。聚合只拼接收齐时已校验的
                # 存量份额。
                return self._retry_session_aggregation(wallet_id, record)
            # collecting 重复投递 / signed 重放：200 同体，不记事件
            return 200, self._session_view(record)

        # 未收过的新份额：collecting/ready 仅接受当前在用快照中的份额；
        # 轮换后失效旧份额与不属于本会话快照的份额一律 400。signed 为
        # 终态，其两份份额必在 received 中，故走到这里的必为非法份额。
        if share_id not in session_ids or share_id not in share_pub:
            raise ServiceError(
                400, f"unknown or inactive share_id {share_id!r}"
            )

        # 新份额：必须是在用份额私钥对 id 与 message 直接拼接载荷的
        # 有效 Ed25519 签名
        payload = crypto.build_payload(session_id, record["message"])
        if not crypto.verify_share(
            bytes.fromhex(share_pub[share_id]), payload, signature
        ):
            raise ServiceError(
                400, f"signature verification failed for {share_id}"
            )

        new_shares = list(record["shares"]) + [
            {"share_id": share_id, "signature": signature.hex()}
        ]
        completes = len(new_shares) == 2
        updated = dict(record)
        updated["shares"] = new_shares
        updated["state"] = "ready" if completes else "collecting"
        # 提交点 1：份额落盘（齐备时转 ready）+ share_received 事件原子
        self._store.update_sign_session(wallet_id, session_id, updated)
        try:
            self._emit(
                wallet_id,
                self._audit_event(
                    audit.TYPE_SESSION_EVENT,
                    request_id=session_id,
                    details={
                        "action": "share_received",
                        "share_id": share_id,
                        "state": updated["state"],
                    },
                ),
            )
        except BaseException:
            self._store.update_sign_session(
                wallet_id, session_id, record
            )
            raise
        record = updated

        if not completes:
            return 201, self._session_view(record)

        # 两份齐备：按既有审批及 hot/cold 门控聚合。门控失败 409 且
        # 保留 ready 供重试（可能原子懒过期审批单）。会话聚合只读取
        # 门控结果，不改动审批单状态（签名对象是会话本身）。
        try:
            self._signing_approval_gate(
                wallet_id, session_id, record["message"]
            )
        except ServiceError:
            return 409, self._session_view(record)
        signed_record = self._commit_session_signed(wallet_id, record)
        return 201, self._session_view(signed_record)

def _retry_session_aggregation(
    self, wallet_id: str, record: dict
) -> tuple[int, dict]:
    """ready 会话重试门控与聚合（重放在用份额触发）。

    门控失败 409、ready 保留；成功转 signed 返回 200（非首次收份额，
    故不是 201），signed 事件只在首次聚合成功时记一次。ready 到点已在
    投递入口原子转 expired（409），终态不会进入本方法。"""
    try:
        self._signing_approval_gate(
            wallet_id, record["id"], record["message"]
        )
    except ServiceError:
        return 409, self._session_view(record)
    signed_record = self._commit_session_signed(wallet_id, record)
    return 200, self._session_view(signed_record)

# -- 会话单节点参与者替换 ----------------------------------------------

def _find_replacement_event(
    self, wallet_id: str, session_id: str, new_share_id: str
) -> dict | None:
    """查找某会话已提交的、生成指定新份额的替换事件（纯只读）。"""
    events = self._audit.session_participant_replaced_events(wallet_id)
    for event in events.get(session_id, []):
        details = event.get("details")
        if (
            isinstance(details, dict)
            and details.get("new_share_id") == new_share_id
        ):
            return event
    return None

def replace_sign_session_participant(
    self,
    wallet_id: str,
    session_id: object,
    replacement_id: object,
    offline_share_id: object,
) -> tuple[int, dict]:
    """替换签名会话的单个参与方份额，返回 (状态码, 会话视图)。

    - 钱包/会话未知 404；replacement_id/offline_share_id 非法 400；
    - 会话非 collecting/ready（含到期懒过期）、目标不是该会话当前在
      用份额 409；
    - 生成 <replacement_id>-share 新 Ed25519 份额替换原槽位：移除旧
      份额已投递签名、保留另一份；旧份额再投递 400，新份额按既有
      Ed25519 校验与审批/hot-cold 门控投递；
    - 首次替换 201；同 replacement_id 同参重放 200、异参 409；
      replacement_id 被其他会话占用 409；已提交重放优先于状态判定；
    - session_participant_replaced 事件为唯一提交点：事件未落盘则
      回滚并删除新份额文件，落盘则前滚迁移会话记录。
    """
    try:
        with self._wallet_lock(wallet_id):
            self._heal_wallet(wallet_id)
            # 404 优先于 400：锁内先判定钱包存在性
            wallet = self._store.get_wallet(wallet_id)
            if wallet is None:
                raise ServiceError(404, f"wallet {wallet_id!r} not found")
            self._validate_session_id(session_id)
            if not isinstance(
                replacement_id, str
            ) or not ROTATION_ID_RE.match(replacement_id):
                raise ServiceError(
                    400, "replacement_id must match [A-Za-z0-9_-]{1,128}"
                )
            if not isinstance(
                offline_share_id, str
            ) or not ROTATION_ID_RE.match(offline_share_id):
                raise ServiceError(
                    400, "offline_share_id must match [A-Za-z0-9_-]{1,128}"
                )
            record = self._store.get_sign_session(wallet_id, session_id)
            if record is None:
                raise ServiceError(
                    404, f"sign session {session_id!r} not found"
                )
            new_share_id = f"{replacement_id}-share"
            # 已提交重放优先：替换事件是唯一提交点。同 id 同参 200、
            # 异参 409；被其他会话占用 409。
            committed = self._audit.session_participant_replaced_events(
                wallet_id
            )
            own_event = None
            for sid, events in committed.items():
                for event in events:
                    details = event.get("details")
                    if (
                        not isinstance(details, dict)
                        or details.get("new_share_id") != new_share_id
                    ):
                        continue
                    if sid == session_id:
                        own_event = event
                    else:
                        raise ServiceError(
                            409,
                            f"replacement {replacement_id!r} is already "
                            "in use",
                        )
            if own_event is not None:
                if own_event["details"].get(
                    "old_share_id"
                ) != offline_share_id:
                    raise ServiceError(
                        409,
                        f"replacement {replacement_id!r} was committed "
                        "with different parameters",
                    )
                # 同参重放：原样返回磁盘视图，不触发懒过期、不记事件
                return 200, self._session_view(record)
            # 懒过期：collecting/ready 到点原子转 expired（仅一次事件）
            record = self._session_expire_if_needed(wallet_id, record)
            if record["state"] == "expired":
                raise ServiceError(
                    409, f"sign session {session_id!r} has expired"
                )
            if record["state"] not in ("collecting", "ready"):
                raise ServiceError(
                    409,
                    f"sign session {session_id!r} is not collecting "
                    "or ready",
                )
            current_ids = list(record["share_ids"])
            if offline_share_id not in current_ids:
                raise ServiceError(
                    409,
                    f"share {offline_share_id!r} is not an in-use share "
                    f"of sign session {session_id!r}",
                )
            if (
                self._store.get_share(wallet_id, new_share_id)
                is not None
            ):
                # 无提交事件的份额文件残留应由持锁自愈清理；仍存在即
                # 占用/矛盾，绝不覆盖来路不明的私钥。
                raise ServiceError(
                    409,
                    f"replacement {replacement_id!r} is already in use",
                )
            # 生成新份额：仅该份额自己的私钥落盘（shares/<W>/<新id>.json，
            # 恰含 private_key/public_key/share_id，64 位小写 hex），
            # 系统中不存在完整私钥。
            key = crypto.generate_share_key(new_share_id)
            self._store.save_share(
                wallet_id,
                {
                    "share_id": new_share_id,
                    "public_key": key.public_bytes.hex(),
                    "private_key": key.private_bytes.hex(),
                },
            )
            # 提交点：session_participant_replaced 事件。事件未落盘则
            # 回滚并删除新份额文件；落盘（含异常但已落盘）则前滚迁移。
            try:
                self._emit(
                    wallet_id,
                    self._audit_event(
                        audit.TYPE_SESSION_PARTICIPANT_REPLACED,
                        request_id=session_id,
                        details={
                            "session_id": session_id,
                            "old_share_id": offline_share_id,
                            "new_share_id": new_share_id,
                        },
                    ),
                )
            except BaseException:
                landed = self._find_replacement_event(
                    wallet_id, session_id, new_share_id

                )
                if landed is None:
                    self._store.delete_share(wallet_id, new_share_id)
                    raise
            # 事件已落盘：前滚迁移会话记录——新份额替换原槽位、移除旧
            # 份额已投递签名、保留另一份；份数不足两份回到 collecting。
            migrated = self._migrate_session_participant(
                record, offline_share_id, new_share_id
            )
            self._store.update_sign_session(
                wallet_id, session_id, migrated
            )
            return 201, self._session_view(migrated)
    except CorruptDataError:
        raise
    except ValueError:
        # wallet_id 含非法字符（构造锁路径时抛出）
        raise ServiceError(400, "invalid wallet_id")

# -- 会话两阶段参与者接管 ----------------------------------------------

@staticmethod
def _takeover_stage_share_id(takeover_id: str, stage: int) -> str:
    return f"{takeover_id}-{stage}-share"

@staticmethod
def _validate_takeover_stage(stage: object) -> None:
    # bool 是 int 的子类，必须先排除；stage 只能是整数 1 或 2
    if (
        not isinstance(stage, int)
        or isinstance(stage, bool)
        or stage not in TAKEOVER_STAGES
    ):
        raise ServiceError(400, "stage must be the integer 1 or 2")

def takeover_sign_session_participant(
    self,
    wallet_id: str,
    session_id: object,
    takeover_id: object,
    stage: object,
    offline_share_id: object,
) -> tuple[int, dict]:
    """两阶段接管签名会话的两个参与方份额，返回 (状态码, 会话视图)。

    请求体恰含 ``takeover_id/stage/offline_share_id``：stage 必须从 1
    起按序提交，两阶段替换会话的**不同槽位**，分别生成
    ``<takeover_id>-1-share``、``<takeover_id>-2-share``。其余迁移、
    私钥落盘边界与单节点替换一致。

    - takeover_id/offline_share_id 非法、stage 非（非布尔）整数 1/2：
      400；钱包/会话未知 404；
    - 阶段首提 201；同阶段同参重放 200 当前视图；异参、跳号（stage 2
      无已提交 stage 1）、终态/到期、offline_share_id 非当前在用份额、
      两阶段命中同一槽位、takeover_id 被其他会话占用或新份额 id 已被
      替换/接管占用：409；已提交重放优先于一切状态判定；
    - session_takeover 事件为唯一提交点（request_id=会话 id，
      actor_id/reason=null，details 恰含
      {takeover_id,stage,old_share_id,new_share_id}）：事件落盘前
      崩溃回滚删新份额，落盘后前滚迁移会话记录。
    """
    try:
        with self._wallet_lock(wallet_id):
            self._heal_wallet(wallet_id)
            # 404 优先于 400：锁内先判定钱包存在性
            wallet = self._store.get_wallet(wallet_id)
            if wallet is None:
                raise ServiceError(404, f"wallet {wallet_id!r} not found")
            self._validate_session_id(session_id)
            if not isinstance(
                takeover_id, str
            ) or not ROTATION_ID_RE.match(takeover_id):
                raise ServiceError(
                    400, "takeover_id must match [A-Za-z0-9_-]{1,128}"
                )
            self._validate_takeover_stage(stage)
            if not isinstance(
                offline_share_id, str
            ) or not ROTATION_ID_RE.match(offline_share_id):
                raise ServiceError(
                    400, "offline_share_id must match [A-Za-z0-9_-]{1,128}"
                )
            record = self._store.get_sign_session(wallet_id, session_id)
            if record is None:
                raise ServiceError(
                    404, f"sign session {session_id!r} not found"
                )
            new_share_id = self._takeover_stage_share_id(
                takeover_id, stage
            )
            stage1_share_id = self._takeover_stage_share_id(
                takeover_id, 1
            )
            # 已提交重放优先：接管事件是唯一提交点。同会话同阶段同参
            # 200、异参 409；同 takeover_id 被其他会话占用 409。
            takeover_events = self._audit.session_takeover_events(
                wallet_id
            )
            committed_replacements = (
                self._audit.session_participant_replaced_events(wallet_id)
            )
            own_event = None
            own_stage1_event = None
            for sid, events in takeover_events.items():
                for event in events:
                    details = event.get("details")
                    if not isinstance(details, dict):
                        continue
                    committed_new = details.get("new_share_id")
                    committed_takeover = details.get("takeover_id")
                    if committed_new == new_share_id:
                        if sid == session_id:
                            own_event = event
                        else:
                            raise ServiceError(
                                409,
                                f"takeover {takeover_id!r} is already "
                                "in use",
                            )
                    if (
                        committed_takeover == takeover_id
                        and sid != session_id
                    ):
                        # 同接管的另一阶段也占用该 takeover_id
                        raise ServiceError(
                            409,
                            f"takeover {takeover_id!r} is already in use",
                        )
                    if (
                        sid == session_id
                        and committed_new == stage1_share_id
                    ):
                        own_stage1_event = event
            # 替换事件同样占用新份额 id 命名空间（replacement_id
            # "<id>-<stage>" 的替换份额恰为 <id>-<stage>-share）
            for sid, events in committed_replacements.items():
                for event in events:
                    details = event.get("details")
                    if (
                        isinstance(details, dict)
                        and details.get("new_share_id") == new_share_id
                    ):
                        raise ServiceError(
                            409,
                            f"share {new_share_id!r} is already in use",
                        )
            if own_event is not None:
                if own_event["details"].get(
                    "old_share_id"
                ) != offline_share_id:
                    raise ServiceError(
                        409,
                        f"takeover {takeover_id!r} stage {stage} was "
                        "committed with different parameters",
                    )
                # 同阶段同参重放：原样返回磁盘视图，不触发懒过期、
                # 不记事件（优先于终态/到期判定）
                return 200, self._session_view(record)
            # 懒过期：collecting/ready 到点原子转 expired（仅一次事件）
            record = self._session_expire_if_needed(wallet_id, record)
            if record["state"] == "expired":
                raise ServiceError(
                    409, f"sign session {session_id!r} has expired"
                )
            if record["state"] not in ("collecting", "ready"):
                raise ServiceError(
                    409,
                    f"sign session {session_id!r} is not collecting "
                    "or ready",
                )
            # stage 必须从 1 起按序提交：stage 2 必须存在同 takeover_id
            # 的已提交 stage 1（跳号 409）。两阶段必须替换不同槽位
            # （槽位按有序位置追踪，见下方 current_ids 计算）。
            if stage == 2 and own_stage1_event is None:
                raise ServiceError(
                    409,
                    f"takeover {takeover_id!r} stage 1 must be "
                    "committed before stage 2",
                )
            current_ids = list(record["share_ids"])
            if offline_share_id not in current_ids:
                raise ServiceError(
                    409,
                    f"share {offline_share_id!r} is not an in-use share "
                    f"of sign session {session_id!r}",
                )
            if stage == 2:
                # 归并本会话全部已提交换槽事件（含 stage 1 及期间可能
                # 穿插的普通替换），按位置判定 stage 2 是否命中 stage 1
                # 已替换的同一物理槽位。
                merged_cuts = sorted(
                    list(
                        committed_replacements.get(session_id, [])
                    )
                    + list(takeover_events.get(session_id, [])),
                    key=lambda event: event.get("seq", 0),
                )
                boundary_sets = self._participant_cut_chain(
                    merged_cuts, current_ids
                )
                stage1_index = next(
                    index
                    for index, event in enumerate(merged_cuts)
                    if event is own_stage1_event
                )
                stage1_old = own_stage1_event["details"]["old_share_id"]
                before_stage1 = boundary_sets[stage1_index]
                if stage1_old not in before_stage1:
                    # 持锁自愈已按事件序列对账，正常不可达；矛盾现场
                    # 绝不静默继续（fail-closed）
                    raise RecoveryError(
                        f"wallet {wallet_id!r} sign session "
                        f"{session_id!r} takeover {takeover_id!r} "
                        "stage 1 slot cannot be reconciled"
                    )
                stage1_slot = before_stage1.index(stage1_old)
                if current_ids.index(offline_share_id) == stage1_slot:
                    raise ServiceError(
                        409,
                        "takeover stage 2 must replace a different slot",
                    )
            if (
                self._store.get_share(wallet_id, new_share_id)
                is not None
            ):
                # 无提交事件的份额文件残留应由持锁自愈清理；仍存在即
                # 占用/矛盾，绝不覆盖来路不明的私钥。
                raise ServiceError(
                    409, f"share {new_share_id!r} is already in use"
                )
            # 生成新阶段份额：仅该份额自己的私钥落盘
            # （shares/<W>/<takeover_id>-<stage>-share.json，恰含
            # private_key/public_key/share_id，64 位小写 hex），
            # 系统中不存在完整私钥。
            key = crypto.generate_share_key(new_share_id)
            self._store.save_share(
                wallet_id,
                {
                    "share_id": new_share_id,
                    "public_key": key.public_bytes.hex(),
                    "private_key": key.private_bytes.hex(),
                },
            )
            # 提交点：session_takeover 事件。事件未落盘则回滚并删除
            # 新份额文件；落盘（含异常但已落盘）则前滚迁移。
            try:
                self._emit(
                    wallet_id,
                    self._audit_event(
                        audit.TYPE_SESSION_TAKEOVER,
                        request_id=session_id,
                        details={
                            "takeover_id": takeover_id,
                            "stage": stage,
                            "old_share_id": offline_share_id,
                            "new_share_id": new_share_id,
                        },
                    ),
                )
            except BaseException:
                landed = self._find_takeover_event(
                    wallet_id, session_id, new_share_id
                )
                if landed is None:
                    self._store.delete_share(wallet_id, new_share_id)
                    raise
            # 事件已落盘：前滚迁移会话记录——新份额替换原槽位、移除
            # 旧份额已投递签名、保留另一份；份数不足两份回到 collecting。
            migrated = self._migrate_session_participant(
                record, offline_share_id, new_share_id
            )
            self._store.update_sign_session(
                wallet_id, session_id, migrated
            )
            return 201, self._session_view(migrated)
    except CorruptDataError:
        raise
    except ValueError:
        # wallet_id 含非法字符（构造锁路径时抛出）
        raise ServiceError(400, "invalid wallet_id")

def _find_takeover_event(
    self, wallet_id: str, session_id: str, new_share_id: str
) -> dict | None:
    """查找某会话已提交的、生成指定新份额的接管事件（纯只读）。"""
    for event in self._audit.session_takeover_events(wallet_id).get(
        session_id, []
    ):
        details = event.get("details")
        if (
            isinstance(details, dict)
            and details.get("new_share_id") == new_share_id
        ):
            return event
    return None

@staticmethod
def _migrate_session_participant(
    record: dict, offline_share_id: str, new_share_id: str
) -> dict:
    """参与者替换/接管提交后的会话前滚：新份额顶替原槽位、剔除旧份额
    已投递签名、保留另一份；不足两份回到 collecting。"""
    current_ids = list(record["share_ids"])
    migrated = dict(record)
    migrated["share_ids"] = [
        new_share_id if sid == offline_share_id else sid
        for sid in current_ids
    ]
    migrated["shares"] = [
        entry
        for entry in record["shares"]
        if entry["share_id"] != offline_share_id
    ]
    migrated["state"] = (
        "ready" if len(migrated["shares"]) == 2 else "collecting"
    )
    migrated.pop("aggregate_signature", None)
    return migrated

@staticmethod
def _participant_cut_chain(
    merged_events: list[dict], final_ids: list[str]
) -> list[list[str]]:
    """按有序换槽事件（每项 details 含 old/new_share_id）与最终有序
    份额集合，反推后正演出每个换槽边界上的有序份额集合。

    返回长度为 ``len(merged_events)+1`` 的列表：首项为首个换槽之前的
    集合，其后依次为每条事件换槽后的集合，末项即 ``final_ids``。
    槽位按下标追踪，用于判定两次换槽（如接管两阶段）是否命中同一
    物理槽位——即使中间穿插了对该槽的普通替换。"""
    initial = list(final_ids)
    for event in reversed(merged_events):
        details = event["details"]
        initial = [
            details["old_share_id"]
            if sid == details["new_share_id"]
            else sid
            for sid in initial
        ]
    boundary_sets = [initial]
    current = initial
    for event in merged_events:
        details = event["details"]
        current = [
            details["new_share_id"]
            if sid == details["old_share_id"]
            else sid
            for sid in current
        ]
        boundary_sets.append(current)
    return boundary_sets

# -- 签名会话严格加载与崩溃恢复 ----------------------------------------

def _rotation_timeline(self, wallet_id: str) -> list[tuple[int, tuple[str, str]]]:
    """返回按 seq 升序的份额轮换激活时间线 [(seq, (share-1, share-2))]。

    恢复据此判定任一审计 seq 时刻"在用两份份额"的快照：首个激活之前
    为创世份额 ("share-1", "share-2")，之后取最近一次激活的 share_ids。
    """
    timeline: list[tuple[int, tuple[str, str]]] = []
    events = self._audit.activated_rotation_events(wallet_id)
    for rotation_id, event in events.items():
        details = event.get("details")
        seq = event.get("seq")
        if not isinstance(details, dict) or not isinstance(seq, int):
            raise RecoveryError(
                f"wallet {wallet_id!r} rotation activation event for "
                f"{rotation_id!r} is malformed"
            )
        share_ids = details.get("share_ids")
        if (
            not isinstance(share_ids, list)
            or len(share_ids) != 2
            or not all(isinstance(sid, str) for sid in share_ids)
        ):
            raise RecoveryError(
                f"wallet {wallet_id!r} rotation activation event for "
                f"{rotation_id!r} has malformed share_ids"
            )
        timeline.append((seq, (share_ids[0], share_ids[1])))
    timeline.sort(key=lambda item: item[0])
    return timeline

@staticmethod
def _active_share_set_at(
    timeline: list[tuple[int, tuple[str, str]]], seq: int
) -> tuple[str, str]:
    active = ("share-1", "share-2")
    for activation_seq, share_ids in timeline:
        if activation_seq <= seq:
            active = share_ids
        else:
            break
    return active

def _validated_replacement_events(
    self, wallet_id: str
) -> dict[str, list[dict]]:
    """读取并严格校验该钱包全部 session_participant_replaced 事件。

    每条事件必须：request_id 为会话 id 且与 details.session_id 一致、
    actor_id/reason 为 null、details 恰含
    {session_id, old_share_id, new_share_id} 三键、old/new 为合法
    份额标识且不同、new 形如 <replacement_id>-share 且全钱包唯一
    （同一新份额不得被两条提交事件引用）。任一不符抛 RecoveryError
    （fail-closed），绝不静默跳过或任取一条。"""
    grouped = self._audit.session_participant_replaced_events(wallet_id)
    seen_new: set[str] = set()
    for session_id, events in grouped.items():
        for event in events:
            if (
                event.get("actor_id") is not None
                or event.get("reason") is not None
            ):
                raise RecoveryError(
                    f"wallet {wallet_id!r} sign session {session_id!r} "
                    "has a participant replacement event with "
                    "actor/reason set"
                )
            details = event.get("details")
            if not isinstance(details, dict) or set(details) != {
                "session_id",
                "old_share_id",
                "new_share_id",
            }:
                raise RecoveryError(
                    f"wallet {wallet_id!r} sign session {session_id!r} "
                    "has a malformed participant replacement event"
                )
            if details["session_id"] != session_id:
                raise RecoveryError(
                    f"wallet {wallet_id!r} participant replacement event "
                    "session_id does not match its request_id"
                )
            old = details["old_share_id"]
            new = details["new_share_id"]
            if not isinstance(old, str) or not _SAFE_SHARE_ID.match(old):
                raise RecoveryError(
                    f"wallet {wallet_id!r} sign session {session_id!r} "
                    "replacement event has a malformed old_share_id"
                )
            if not isinstance(
                new, str
            ) or not REPLACEMENT_SHARE_ID_RE.match(new):
                raise RecoveryError(
                    f"wallet {wallet_id!r} sign session {session_id!r} "
                    "replacement event has a malformed new_share_id"
                )
            if old == new:
                raise RecoveryError(
                    f"wallet {wallet_id!r} sign session {session_id!r} "
                    "replacement event replaces a share with itself"
                )
            if new in seen_new:
                raise RecoveryError(
                    f"wallet {wallet_id!r} replacement share {new!r} is "
                    "committed by more than one event"
                )
            seen_new.add(new)
    return grouped

def _validated_takeover_events(
    self, wallet_id: str
) -> dict[str, list[dict]]:
    """读取并严格校验该钱包全部 session_takeover 事件。

    每条事件必须：request_id 为会话 id、actor_id/reason 为 null、
    details 恰含 {takeover_id, stage, old_share_id, new_share_id}
    四键、takeover_id 为安全标识、stage 为非布尔整数 1/2、old 为合法
    份额标识、new 恰为 <takeover_id>-<stage>-share、old != new、
    new 全钱包唯一、同一 takeover_id 不跨会话。同一 takeover_id 的
    阶段必须按 seq 从 1 起连续（stage 2 之前必有 stage 1、不重复、
    不跳号）；两阶段必须替换不同物理槽位（按提交时刻有序快照下标
    判定，见 _recover_one_sign_session）。任一不符抛 RecoveryError
    （fail-closed），绝不静默跳过。"""
    grouped = self._audit.session_takeover_events(wallet_id)
    seen_new: set[str] = set()
    seen_takeover_sessions: dict[str, str] = {}
    for session_id, events in grouped.items():
        stages_by_takeover: dict[str, list[dict]] = {}
        for event in events:
            if (
                event.get("actor_id") is not None
                or event.get("reason") is not None
            ):
                raise RecoveryError(
                    f"wallet {wallet_id!r} sign session {session_id!r} "
                    "has a takeover event with actor/reason set"
                )
            details = event.get("details")
            if not isinstance(details, dict) or set(details) != {
                "takeover_id",
                "stage",
                "old_share_id",
                "new_share_id",
            }:
                raise RecoveryError(
                    f"wallet {wallet_id!r} sign session {session_id!r} "
                    "has a malformed takeover event"
                )
            takeover_id = details["takeover_id"]
            stage = details["stage"]
            old = details["old_share_id"]
            new = details["new_share_id"]
            if not isinstance(
                takeover_id, str
            ) or not ROTATION_ID_RE.match(takeover_id):
                raise RecoveryError(
                    f"wallet {wallet_id!r} sign session {session_id!r} "
                    "takeover event has a malformed takeover_id"
                )
            # 同一 takeover_id 不得跨会话占用（在线 409 已挡住，落盘
            # 仍出现即外部篡改/矛盾现场，fail-closed）。
            owner = seen_takeover_sessions.get(takeover_id)
            if owner is not None and owner != session_id:
                raise RecoveryError(
                    f"wallet {wallet_id!r} takeover {takeover_id!r} is "
                    "committed for more than one session"
                )
            seen_takeover_sessions[takeover_id] = session_id
            if (
                not isinstance(stage, int)
                or isinstance(stage, bool)
                or stage not in TAKEOVER_STAGES
            ):
                raise RecoveryError(
                    f"wallet {wallet_id!r} sign session {session_id!r} "
                    "takeover event has a malformed stage"
                )
            if not isinstance(old, str) or not _SAFE_SHARE_ID.match(old):
                raise RecoveryError(
                    f"wallet {wallet_id!r} sign session {session_id!r} "
                    "takeover event has a malformed old_share_id"
                )
            if (
                not isinstance(new, str)
                or new != self._takeover_stage_share_id(takeover_id, stage)
            ):
                raise RecoveryError(
                    f"wallet {wallet_id!r} sign session {session_id!r} "
                    "takeover event has a malformed new_share_id"
                )
            if old == new:
                raise RecoveryError(
                    f"wallet {wallet_id!r} sign session {session_id!r} "
                    "takeover event replaces a share with itself"
                )
            if new in seen_new:
                raise RecoveryError(
                    f"wallet {wallet_id!r} takeover share {new!r} is "
                    "committed by more than one event"
                )
            seen_new.add(new)
            stages_by_takeover.setdefault(takeover_id, []).append(event)
        for takeover_id, takeover_events in stages_by_takeover.items():
            # 事件已按 seq 升序：阶段序列必须恰为 [1] 或 [1, 2]
            stages = [
                event["details"]["stage"] for event in takeover_events
            ]
            if stages not in ([1], [1, 2]):
                raise RecoveryError(
                    f"wallet {wallet_id!r} sign session {session_id!r} "
                    f"takeover {takeover_id!r} has a non-contiguous "
                    "stage sequence"
                )
    return grouped

def _recover_sign_sessions(self, wallet_id: str) -> None:
    """启动/持锁恢复签名会话崩溃现场（调用方须持钱包事务锁）。

    形状/UTC 时间严格校验由存储层完成（损坏即 CorruptDataError ->
    503/阻止就绪，保留现场）。对账以 session_event 为唯一提交点：

    - 无 created 事件：创建未提交，删除残留会话记录；有 created 事件
      却无记录：矛盾现场，fail-closed；
    - 动作序列严格校验：created 首个且唯一；share_received 的份额必须
      属于该事件时刻的在用快照、不重复，details.state 与当时有效已收
      份数一致（齐份 ready，否则 collecting）；expired/signed 至多一次
      且互斥、其后不得再有事件；signed 时两份份额必已齐；created 的
      message/timeout_seconds 必须与记录一致；
    - 已存份额若无对应 share_received 事件：份额提交未完成，回滚丢弃；
      有事件却无已存份额：仅当该份额已被后续轮换激活淘汰（剔除旧份额
      的迁移）才合法，否则 fail-closed；
    - 每份已存签名用其对应历史公钥重新校验；signed 按有序快照重算
      128 字节聚合签名，必须与记录一致，否则 fail-closed；
    - signed 事件：前滚为唯一 signed；expired 事件（collecting 与
      ready 到点均可过期）：前滚 expired；否则按当前在用快照迁移并据
      已提交份额恢复 collecting/ready——磁盘误写的终态随事件回滚；
    - collecting/ready 记录若停留在旧快照，按钱包当前在用份额迁移：
      剔除已收旧份额（其 share_received 事件保留在仅追加审计中）。
    恢复本身不记事件、不分配 seq。
    """
    records = self._store.list_sign_sessions(wallet_id)
    # 仅当会话文件存在时才做审计对账：文件不存在是正常空状态，绝不
    # 触碰审计日志（使审计文件损坏时不依赖审计的路由仍可用）；但文件
    # 存在（即使为 {}）而审计里有 created 事件，属于“记录丢失/被清空”
    # 的矛盾现场，必须读取审计并 fail-closed。
    file_exists = self._store.sign_session_file_exists(wallet_id)
    if not file_exists:
        return
    events_by_session = self._audit.session_events(wallet_id)
    replacement_events = self._validated_replacement_events(wallet_id)
    takeover_events = self._validated_takeover_events(wallet_id)
    timeline = self._rotation_timeline(wallet_id)
    wallet = self._store.get_wallet(wallet_id)
    if records and not isinstance(wallet, dict):
        raise RecoveryError(
            f"wallet {wallet_id!r} metadata missing during session recovery"
        )
    current_ids: tuple[str, str] | None = None
    if isinstance(wallet, dict):
        shares = wallet.get("shares")
        if (
            not isinstance(shares, list)
            or len(shares) != 2
            or not all(isinstance(s, dict) for s in shares)
        ):
            raise RecoveryError(
                f"wallet {wallet_id!r} metadata shares are malformed"
            )
        current_ids = (shares[0]["share_id"], shares[1]["share_id"])

    recorded_ids = {record["id"] for record in records}
    for session_id, session_events in events_by_session.items():
        ordered = sorted(session_events, key=lambda e: e.get("seq", 0))
        if any(
            isinstance(e.get("details"), dict)
            and e["details"].get("action") == "created"
            for e in ordered
        ) and session_id not in recorded_ids:
            raise RecoveryError(
                f"wallet {wallet_id!r} sign session {session_id!r} has a "
                "created event but no session record"
            )

    # 已提交替换/接管事件引用的会话必须存在；其新份额文件必须密码学
    # 自洽（缺失/损坏/矛盾 fail-closed，保留现场）。两类事件共享新份额
    # id 命名空间，任一 new_share_id 被两类事件重复引用均属矛盾现场。
    committed_new_share_ids: set[str] = set()
    participant_events = {
        "replacement": replacement_events,
        "takeover": takeover_events,
    }
    for kind, grouped in participant_events.items():
        for session_id, events in grouped.items():
            if session_id not in recorded_ids:
                raise RecoveryError(
                    f"wallet {wallet_id!r} sign session {session_id!r} "
                    f"has a participant {kind} event but no session record"
                )
            for event in events:
                new_id = event["details"]["new_share_id"]
                if new_id in committed_new_share_ids:
                    raise RecoveryError(
                        f"wallet {wallet_id!r} participant share "
                        f"{new_id!r} is committed by more than one event"
                    )
                committed_new_share_ids.add(new_id)
                self._validated_replacement_share(wallet_id, new_id)
    # 无提交事件引用的 *-share 份额文件是替换/接管提交点（事件）落盘
    # 前的崩溃残留：回滚删除。
    for share_id in self._store.list_share_files(wallet_id):
        if (
            share_id.endswith("-share")
            and share_id not in committed_new_share_ids
        ):
            self._store.delete_share(wallet_id, share_id)

    for record in records:
        self._recover_one_sign_session(
            wallet_id,
            record,
            events_by_session,
            timeline,
            current_ids,
            wallet,
            replacement_events.get(record["id"], []),
            takeover_events.get(record["id"], []),
        )

def _recover_one_sign_session(
    self,
    wallet_id: str,
    record: dict,
    events_by_session: dict[str, list[dict]],
    timeline: list[tuple[int, tuple[str, str]]],
    current_ids: tuple[str, str] | None,
    wallet: dict,
    replacements: list[dict] | None = None,
    takeovers: list[dict] | None = None,
) -> None:
    session_id = record["id"]
    replacements = replacements or []
    takeovers = takeovers or []
    raw_events = sorted(
        events_by_session.get(session_id, []),
        key=lambda event: event.get("seq", 0),
    )
    session_events: list[dict] = []
    for event in raw_events:
        details = event.get("details")
        if not isinstance(details, dict):
            raise RecoveryError(
                f"wallet {wallet_id!r} sign session {session_id!r} has a "
                "session_event without object details"
            )
        session_events.append(event)

    actions = [event["details"].get("action") for event in session_events]
    if not session_events or actions[0] != "created" or actions.count(
        "created"
    ) != 1:
        # created 必须是首个动作且唯一；无 created 事件 -> 创建未提交，
        # 回滚删除残留记录（事件未落盘的残留记录重启即清）。
        if "created" not in actions:
            if replacements or takeovers:
                # 创建未提交却有已提交替换/接管事件：矛盾现场，绝不删除
                raise RecoveryError(
                    f"wallet {wallet_id!r} sign session {session_id!r} "

                f"wallet {wallet_id!r} sign session {session_id!r} "
                "has participant replacement/takeover events but no "
                "created event"
            )
        self._store.delete_sign_session(wallet_id, session_id)
        return
    raise RecoveryError(
        f"wallet {wallet_id!r} sign session {session_id!r} has a "
        "malformed created action sequence"
    )

created_details = session_events[0]["details"]
if (
    created_details.get("message") != record["message"]
    or created_details.get("timeout_seconds")
    != record["timeout_seconds"]
):
    raise RecoveryError(
        f"wallet {wallet_id!r} sign session {session_id!r} created "
        "event does not match the record"
    )

# 已提交参与者替换/接管事件：必须发生在创建之后、终态之前；每次
# 换槽的 old 必须是该事件时刻会话快照内的在用份额、new 不得已在
# 快照中。首个替换/接管之后会话快照与钱包轮换解耦（轮换不再迁移
# 该会话）。两类事件共享同一条换槽序列，按 seq 归并。
participant_cuts: list[tuple[int, str, str]] = []
merged_participant_events = sorted(
    list(replacements) + list(takeovers),
    key=lambda event: event.get("seq", 0),
)
if merged_participant_events:
    created_seq = session_events[0].get("seq")
    current_set = list(
        self._active_share_set_at(
            timeline, merged_participant_events[0]["seq"]
        )
    )
    last_seq = created_seq
    for event in merged_participant_events:
        seq = event.get("seq")
        if (
            not isinstance(seq, int)
            or isinstance(seq, bool)
            or not isinstance(last_seq, int)
            or seq <= last_seq
        ):
            raise RecoveryError(
                f"wallet {wallet_id!r} sign session {session_id!r} "
                "has an out-of-order participant replacement/"
                "takeover event"
            )
        last_seq = seq
        details = event["details"]
        old, new = details["old_share_id"], details["new_share_id"]
        if old not in current_set or new in current_set:
            raise RecoveryError(
                f"wallet {wallet_id!r} sign session {session_id!r} "
                f"replacement of {old!r} by {new!r} does not match "
                "the session share set at its seq"
            )
        current_set = [
            new if sid == old else sid for sid in current_set
        ]
        participant_cuts.append((seq, old, new))

def session_set_at(seq: int) -> tuple[str, str]:
    """该会话在指定审计 seq 时刻的在用份额快照。

    首个替换/接管事件之前跟随钱包轮换时间线；之后与轮换解耦，按
    换槽事件逐次换槽（冻结于最后一次替换/接管后的快照）。"""
    if not participant_cuts or seq < participant_cuts[0][0]:
        return self._active_share_set_at(timeline, seq)
    current = list(
        self._active_share_set_at(timeline, participant_cuts[0][0])
    )
    for cut_seq, old, new in participant_cuts:
        if cut_seq > seq:
            break
        current = [new if sid == old else sid for sid in current]
    return (current[0], current[1])

# 两阶段接管的槽位约束：同一 takeover_id 的两个阶段必须替换不同
# 物理槽位（按各自提交时刻的有序快照下标判定；其间该槽位可能又
# 被普通替换/其他接管换过份额，故必须按位置而不是按份额 id 判定）。
takeover_by_id: dict[str, list[dict]] = {}
for event in takeovers:
    takeover_by_id.setdefault(
        event["details"]["takeover_id"], []
    ).append(event)
for takeover_id, tid_events in takeover_by_id.items():
    if len(tid_events) != 2:
        continue
    first, second = tid_events
    first_seq = first.get("seq")
    second_seq = second.get("seq")
    first_old = first["details"]["old_share_id"]
    second_old = second["details"]["old_share_id"]
    before_first = session_set_at(first_seq - 1)
    before_second = session_set_at(second_seq - 1)
    if (
        first_old not in before_first
        or second_old not in before_second
    ):
        # 通用换槽校验已保证 old 属于其提交时刻快照，此处为防御
        raise RecoveryError(
            f"wallet {wallet_id!r} sign session {session_id!r} "
            f"takeover {takeover_id!r} does not match the session "
            "share set at its seq"
        )
    if before_first.index(first_old) == before_second.index(
        second_old
    ):
        raise RecoveryError(
            f"wallet {wallet_id!r} sign session {session_id!r} "
            f"takeover {takeover_id!r} replaces the same slot twice"
        )

# 严格校验动作顺序，并重建各动作提交时刻的已收份额序列。
# committed_events: 按 seq 顺序的 share_received 事件（跨轮换）。
committed_events: list[dict] = []
terminal: str | None = None
for event in session_events[1:]:
    details = event["details"]
    action = details.get("action")
    seq = event.get("seq")
    if terminal is not None:
        raise RecoveryError(
            f"wallet {wallet_id!r} sign session {session_id!r} has an "
            f"action {action!r} after terminal {terminal!r}"
        )
    if action == "share_received":
        sid = details.get("share_id")
        state_detail = details.get("state")
        if state_detail not in ("collecting", "ready"):
            raise RecoveryError(
                f"wallet {wallet_id!r} sign session {session_id!r} "
                "share_received event has malformed state"
            )
        if not isinstance(sid, str) or not sid:
            raise RecoveryError(
                f"wallet {wallet_id!r} sign session {session_id!r} "
                "share_received event has malformed share_id"
            )
        active_set = session_set_at(seq)
        if sid not in active_set:
            raise RecoveryError(
                f"wallet {wallet_id!r} sign session {session_id!r} "
                f"received share {sid!r} that was not active at seq "
                f"{seq!r}"
            )
        if any(
            e["details"].get("share_id") == sid
            for e in committed_events
        ):
            raise RecoveryError(
                f"wallet {wallet_id!r} sign session {session_id!r} "
                f"recorded share {sid!r} twice"
            )
        committed_events.append(event)
        # details.state 必须与该时刻有效快照内已收份数一致：
        # 轮换淘汰旧份额后份数重新计数。
        effective = [
            e
            for e in committed_events
            if e["details"]["share_id"]
            in session_set_at(seq)
        ]
        expected_state = (
            "ready" if len(effective) == 2 else "collecting"
        )
        if state_detail != expected_state:
            raise RecoveryError(
                f"wallet {wallet_id!r} sign session {session_id!r} "
                f"share_received state {state_detail!r} does not match "
                f"the effective share count"
            )
    elif action == "signed":
        if details.get("state") != "signed":
            raise RecoveryError(
                f"wallet {wallet_id!r} sign session {session_id!r} "
                "signed event has malformed state"
            )
        active_set = session_set_at(seq)
        effective = [
            e
            for e in committed_events
            if e["details"]["share_id"] in active_set
        ]
        if len(effective) != 2:
            raise RecoveryError(
                f"wallet {wallet_id!r} sign session {session_id!r} "
                "signed event without both shares committed"
            )
        terminal = "signed"
    elif action == "expired":
        if details.get("state") != "expired":
            raise RecoveryError(
                f"wallet {wallet_id!r} sign session {session_id!r} "
                "expired event has malformed state"
            )
        terminal = "expired"
    else:
        raise RecoveryError(
            f"wallet {wallet_id!r} sign session {session_id!r} has "
            f"unknown action {action!r}"
        )

if actions.count("signed") + actions.count("expired") > 1:
    raise RecoveryError(
        f"wallet {wallet_id!r} sign session {session_id!r} has multiple "
        "terminal actions"
    )

signed_seq = next(
    (
        e["seq"]
        for e in session_events
        if e["details"].get("action") == "signed"
    ),
    None,
)
expired_seq = next(
    (
        e["seq"]
        for e in session_events
        if e["details"].get("action") == "expired"
    ),
    None,
)

# 终态冻结其提交时刻的在用快照；非终态以钱包当前在用份额为准
# （有替换/接管事件的会话冻结于最后一次换槽后的快照，不再随轮换
# 迁移）。
terminal_seq = signed_seq or expired_seq
for cut_seq, _old, _new in participant_cuts:
    if terminal_seq is not None and cut_seq > terminal_seq:
        raise RecoveryError(
            f"wallet {wallet_id!r} sign session {session_id!r} has a "
            "participant replacement/takeover event after its "
            "terminal action"
        )
if terminal == "signed":
    effective_ids = session_set_at(signed_seq)
elif terminal == "expired":
    effective_ids = session_set_at(expired_seq)
elif participant_cuts:
    effective_ids = session_set_at(participant_cuts[-1][0])
else:
    if current_ids is None:
        raise RecoveryError(
            f"wallet {wallet_id!r} metadata missing during session "
            "recovery"
        )
    effective_ids = current_ids

committed_ids = [
    event["details"]["share_id"] for event in committed_events
]
committed_set = set(committed_ids)
stored_all = {entry["share_id"]: entry for entry in record["shares"]}

# 已存份额若无提交事件：份额落盘先于事件追加，这是收份额崩溃
# 窗口内"状态已写、提交点（事件）未落盘"的现场 -> 确定回滚，
# rebuilt 时自然剔除该未提交份额（不留孤立份额）。
stored = {
    sid: entry
    for sid, entry in stored_all.items()
    if sid in committed_set
}

# 已提交却未存储的份额：唯一合法解释是该份额在投递落事件之后、
# 会话终态（若有）之前，被某次轮换激活或参与者替换从在用快照中
# 淘汰（迁移时剔除已收旧份额，仅追加审计保留其 share_received
# 事件）。终态之后的轮换/替换不能解释终态记录中的缺失。
for sid in committed_ids:
    if sid in stored:
        continue
    if sid in effective_ids:
        raise RecoveryError(
            f"wallet {wallet_id!r} sign session {session_id!r} has a "
            f"committed share {sid!r} but no stored signature"
        )
    event_seq = next(
        e["seq"]
        for e in committed_events
        if e["details"]["share_id"] == sid
    )
    evicted = False
    for act_seq, act_ids in timeline:
        if act_seq <= event_seq:
            continue
        if terminal_seq is not None and act_seq > terminal_seq:
            continue
        if (
            sid not in act_ids
            and sid
            in self._active_share_set_at(timeline, act_seq - 1)
        ):
            evicted = True
            break
    if not evicted:
        for cut_seq, old, _new in participant_cuts:
            if cut_seq <= event_seq:
                continue
            if terminal_seq is not None and cut_seq > terminal_seq:
                continue
            if old == sid:
                evicted = True
                break
    if not evicted:
        raise RecoveryError(
            f"wallet {wallet_id!r} sign session {session_id!r} "
            f"committed share {sid!r} vanished without a rotation "
            "or participant replacement/takeover"
        )

# 非终态记录的 share_ids 必须等于某一历史时刻的在用快照；终态记录
# 的 share_ids 必须冻结为终态提交时刻快照。
historical_sets = {("share-1", "share-2")}
for act_seq, act_ids in timeline:
    historical_sets.add(
        self._active_share_set_at(timeline, act_seq)
    )
if participant_cuts:
    current_set = list(
        self._active_share_set_at(timeline, participant_cuts[0][0])
    )
    for _cut_seq, old, new in participant_cuts:
        current_set = [
            new if sid == old else sid for sid in current_set
        ]
        historical_sets.add((current_set[0], current_set[1]))
recorded_ids = tuple(record["share_ids"])
if recorded_ids not in historical_sets:
    raise RecoveryError(
        f"wallet {wallet_id!r} sign session {session_id!r} snapshot "
        f"{recorded_ids!r} matches no known share set"
    )
if terminal is not None and recorded_ids != effective_ids:
    raise RecoveryError(
        f"wallet {wallet_id!r} sign session {session_id!r} terminal "
        "snapshot does not match the active shares at commit time"
    )

# 用相应公钥重新校验每份已存签名（历史份额公钥沿轮换记录链解析）。
verify_ids = sorted(stored)
public_map = self._session_share_public_keys(
    wallet_id, verify_ids, wallet
)
payload = crypto.build_payload(session_id, record["message"])
for sid, entry in stored.items():
    signature = bytes.fromhex(entry["signature"])
    if not crypto.verify_share(
        bytes.fromhex(public_map[sid]), payload, signature
    ):
        raise RecoveryError(
            f"wallet {wallet_id!r} sign session {session_id!r} stored "
            f"signature for {sid!r} fails public-key verification"
        )

rebuilt = dict(record)
rebuilt["share_ids"] = list(effective_ids)
rebuilt["shares"] = [
    stored[sid]
    for sid in effective_ids
    if sid in stored
]
rebuilt.pop("aggregate_signature", None)

if terminal == "signed":
    if len(rebuilt["shares"]) != 2:
        raise RecoveryError(
            f"wallet {wallet_id!r} sign session {session_id!r} signed "
            "without both stored shares"
        )
    rebuilt["state"] = "signed"
    rebuilt["aggregate_signature"] = (
        self._aggregate_session_shares(rebuilt).hex()
    )
    # 记录带有聚合签名时，重算结果必须一致（被篡改即 fail-closed）；
    # 记录恰缺聚合签名（signed 已提交、状态写盘不完整的崩溃现场）
    # 时按事件前滚补齐即可。
    recorded_aggregate = record.get("aggregate_signature")
    if (
        isinstance(recorded_aggregate, str)
        and recorded_aggregate != rebuilt["aggregate_signature"]
    ):
        raise RecoveryError(
            f"wallet {wallet_id!r} sign session {session_id!r} "
            "aggregate signature does not recompute to the record"
        )
elif terminal == "expired":
    # collecting 与 ready 到点均可过期：终态不再聚合。
    rebuilt["state"] = "expired"
else:
    # 轮换迁移后的非终态：旧份额已剔除，按当前快照内已提交份数恢复
    rebuilt["state"] = (
        "ready" if len(rebuilt["shares"]) == 2 else "collecting"
    )

if rebuilt != record:
    self._store.update_sign_session(
        wallet_id, session_id, rebuilt
    )

content.content:
        "request_expired",
        "request_signed",
        "share_rotation_prepared",
        "share_rotation_activated",
        "asset_operation_committed",
        "transaction_policy_updated",
        "session_event",
        "session_participant_replaced",
        "session_takeover",
    )
)


def _verify_audit_contract(wallet_id: str, files: dict[str, bytes]) -> None:
    """审计日志契约校验：顶层契约键、事件恰七字段、类型为封闭已知集合。

    seq 连续性与各类型的语义对账由线上恢复器（check_log/轮换链/账本/会话/
    审批单对账）负责；这里拦住夹带额外字段或未知事件类型的日志——审计是
    恢复提交点的唯一依据，未识别类型不得静默带入恢复后的系统。
    """
    rel = f"audit/{wallet_id}.json"
    if rel not in files:
        return
    log = _load_json_object(files[rel], "audit file")
    if not set(log) <= _AUDIT_LOG_KEYS:
        raise BackupError(503, "audit file has an unexpected top-level key")
    recorded_wallet = log.get("wallet_id")
    if recorded_wallet is not None and recorded_wallet != wallet_id:
        raise BackupError(503, "audit file wallet_id does not match")
    events = log.get("events")
    if not isinstance(events, list):
        raise BackupError(503, "audit file events must be a list")
    for event in events:
        if not isinstance(event, dict) or set(event) != _AUDIT_EVENT_KEYS:
            raise BackupError(503, "audit event has an unexpected shape")
        if event.get("type") not in _KNOWN_AUDIT_TYPES:
            raise BackupError(503, "audit file has an unknown event type")


def _validate_manifest_shape(
    manifest: object, files: dict[str, bytes]
) -> dict:
    """校验 manifest v1 形状、成员清单与每项字节/sha256，以及 S 绑定哈希。

    manifest 顶层与每个 files 项都只允许契约键：任何额外键（夹带的标识、
    私钥材料或未知扩展）一律 503，绝不静默忽略后继续。"""
    if not isinstance(manifest, dict):
        raise BackupError(503, "manifest is not a JSON object")
    if not set(manifest) <= _MANIFEST_TOP_KEYS:
        raise BackupError(503, "manifest has an unexpected top-level key")
    if manifest.get("version") != MANIFEST_VERSION:
        raise BackupError(503, "unsupported manifest version")
    wallet_id = manifest.get("wallet_id")
    snapshot_id = manifest.get("snapshot_id")
    if not is_safe_id(wallet_id) or not is_safe_id(snapshot_id):
        raise BackupError(503, "manifest has invalid wallet or snapshot id")
    entries = manifest.get("files")
    if not isinstance(entries, list):
        raise BackupError(503, "manifest files must be a list")
    bound = manifest.get("manifest_sha256")
    if not isinstance(bound, str) or not _is_sha256_hex(bound):
        raise BackupError(503, "manifest is missing its binding hash")
    if sha256_hex(_canonical_manifest_body(manifest)) != bound:
        raise BackupError(503, "manifest binding hash mismatch")
    # 归一为"规范主体 + 绑定哈希"：保证同 S 同哈希的重放返回与首次逐字节
    # 一致的 manifest（同体），忽略包内任何额外键/排版差异。
    normalized = json.loads(_canonical_manifest_body(manifest))
    normalized["manifest_sha256"] = bound
    seen: set[str] = set()
    prev_path: Optional[str] = None
    for entry in entries:
        if not isinstance(entry, dict):
            raise BackupError(503, "manifest entry is not an object")
        if not set(entry) <= _MANIFEST_ENTRY_KEYS:
            raise BackupError(503, "manifest entry has an unexpected key")
        path = entry.get("path")
        nbytes = entry.get("bytes")
        digest = entry.get("sha256")
        if not isinstance(path, str) or path in seen:
            raise BackupError(503, "manifest has a missing or duplicate path")
        # 契约要求 files 项严格按 path 升序：即使绑定哈希自洽（包可被整体
        # 重造），乱序清单也不是合法快照形状，绝不据其恢复或落 committed。
        if prev_path is not None and path <= prev_path:
            raise BackupError(503, "manifest files are not sorted by path")
        prev_path = path
        seen.add(path)
        if not _is_whitelisted(wallet_id, path):
            raise BackupError(503, "manifest lists a non-whitelisted path")
        if not isinstance(nbytes, int) or isinstance(nbytes, bool) or nbytes < 0:
            raise BackupError(503, "manifest entry has a bad byte count")
        if not isinstance(digest, str) or not _is_sha256_hex(digest):
            raise BackupError(503, "manifest entry has a bad sha256")
        data = files.get(path)
        if data is None or len(data) != nbytes or sha256_hex(data) != digest:
            raise BackupError(503, "snapshot file fails its manifest hash")
    extra = set(files) - seen
    if extra:
        raise BackupError(503, "snapshot contains files absent from the manifest")
    if not any(p == f"wallets/{wallet_id}.json" for p in seen):
        raise BackupError(503, "snapshot is missing the wallet metadata file")
    # 激活备份（*.bak.json）只是激活事务窗口内的瞬态文件，持锁备份前的
    # 自愈必然已回滚/清理：合法快照里出现它们等于打包了半状态，拒绝。
    if any(
        p.startswith(f"rotation-staging/{wallet_id}/")
        and p.endswith(".bak.json")
        for p in seen
    ):
        raise BackupError(503, "snapshot must not carry transient rotation backups")
    return normalized


def _load_json_object(data: bytes, what: str) -> dict:
    try:
        value = json.loads(data.decode("utf-8"))
    except (ValueError, UnicodeDecodeError) as exc:
        raise BackupError(503, f"{what} is not valid JSON") from exc
    if not isinstance(value, dict):
        raise BackupError(503, f"{what} must be a JSON object")
    return value


