        if not isinstance(value, str) or not ROTATION_ID_RE.match(value):
            raise ServiceError(400, "node must match [A-Za-z0-9_-]{1,128}")

    @staticmethod
    def _validate_dkg_hex64_or_null(value: object, name: str) -> None:
